-- ============================================================================
-- D5 EXPERT DEEP SEED: Applied AI and Language Models, advanced tier.
--
-- Six modules, 26 lessons, 132 questions. Generated from the tier's
-- manifest.json and the committed bank JSONs under
-- tools/course-banks/appliedai/advanced.
--
-- What this tier owns: AGREEMENT, CALIBRATION AND GOVERNANCE. Two annotators
-- and Cohen's kappa, unweighted and weighted; calibration with the Brier
-- score, the reliability table, ECE and MCE; the Murphy decomposition with the
-- within-bin terms and the bin-edge rule; log loss imported from the machine
-- learning engine; judged sets, pooling, unjudged passages and test questions
-- in a prompt; every boundary rule, the tie key, the bootstrap levels and the
-- caps; the conventions that are choices, when a model helper is never graded,
-- and the evaluation report. Digest sections 17 to 23, and section 24.
--
-- THE TRAP THE TIER IS BUILT ON. A score is only as good as its judgments and
-- its bins: the second annotator's grades reverse the nDCG order of the two
-- systems, and an interior bin edge moves the reliability term.
-- ============================================================================

values ('appliedai', 'advanced', '{"modules":[{"key":"m01-annotator-agreement","title":"Annotator Agreement","lesson_keys":["l01-two-annotators-one-judged-set","l02-observed-and-expected-agreement","l03-cohens-kappa","l04-weighted-kappa","l05-when-kappa-is-undefined"]},{"key":"m02-calibration","title":"Calibration","lesson_keys":["l01-a-probability-and-an-outcome","l02-the-brier-score","l03-the-reliability-table","l04-ece-and-mce"]},{"key":"m03-decomposing-the-brier-score","title":"Decomposing the Brier Score","lesson_keys":["l01-reliability-resolution-uncertainty","l02-the-within-bin-terms","l03-the-bin-edge-rule","l04-log-loss-from-the-ml-engine"]},{"key":"m04-judged-sets-and-leakage","title":"Judged Sets, Pooling and Leakage","lesson_keys":["l01-how-the-judged-set-was-pooled","l02-unjudged-is-not-irrelevant","l03-pooling-bias","l04-test-questions-in-a-prompt","l05-a-second-annotator-as-a-check"]},{"key":"m05-boundaries-ties-and-caps","title":"Boundaries, Ties and Caps","lesson_keys":["l01-boundaries-rule-by-rule","l02-the-twelve-digit-tie-key","l03-bootstrap-levels-and-labels","l04-row-and-size-caps"]},{"key":"m06-reading-the-engine-honestly","title":"Reading the Engine Honestly","lesson_keys":["l01-conventions-that-are-choices","l02-when-a-model-helper-is-never-graded","l03-writing-the-evaluation-report","l04-the-capstone-brief"]}]}'::jsonb, 1)
