insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('appliedai', 'advanced', 'module', 'm01-annotator-agreement', 1, 'The Ekene annotators graded the same 183 judged pairs. What is their observed agreement, and how does the engine get it?', '["0.336708: every row total times its column total, summed and divided by 183 squared", "0.579841: the share of the 183 pairs that remain in agreement once chance is taken away", "0.721311: the pairs on the diagonal of the confusion table, divided by the 183 pairs", "0.814208: the pairs both annotators placed on the same side of the grade 1 line, over 183"]'::jsonb, 2, 'The engine''s basis says observedAgreement = diagonal / n, a count over a count: 0.721311. The row-times-column sum over n squared is the expected agreement, 0.336708. The unweighted kappa, 0.579841, rescales the observed figure against the expected one. 0.814208 is the observed agreement after each grade is reduced to relevant or not at grade 1 or more, a different set of ratings.'),
  ('appliedai', 'advanced', 'module', 'm01-annotator-agreement', 2, 'Rater a gave grade 0 to 101 of the pairs and rater b to 77. What does the expected agreement of 0.336708 describe?', '["What two raters with these row and column totals would agree on if each labelled at random", "The share of pairs the second annotator''s draw left unchanged from the primary grade", "How often the pair would agree once both have read the passage with care, by the fixture", "The agreement of rater a with itself when the same pairs are graded a second time over"]'::jsonb, 0, 'Expected agreement is the sum of row total times column total over n squared: the agreement two independent raters would reach while keeping their own mix of grades. Both annotators lean on grade 0, so a large part of their agreement was always going to happen. It is computed from the margins alone, so it says nothing about the draw, about care in reading, or about a rater graded twice.'),
  ('appliedai', 'advanced', 'module', 'm01-annotator-agreement', 3, 'Which calculation gives the unweighted kappa of 0.579841 on the Ekene annotators, in the form the engine writes it?', '["The observed agreement divided by the expected agreement, 0.721311 over 0.336708 in full", "1 - sum w O / sum w E, with w equal to |i - j|, since the grades form an ordered scale", "The mean of the three kappas the engine returns under the none, linear and quadratic weights", "1 - sum w O / sum w E, with w 0 on the diagonal and 1 off it: 1 - 0.278689 / 0.663292"]'::jsonb, 3, 'The basis writes kappa as 1 - sum w O / sum w E, and the unweighted weights are 0 on the diagonal and 1 off it, so the ratio is the observed disagreement 0.278689 over the expected disagreement 0.663292. A plain ratio of the two agreements is no kappa and could exceed 1. Weights of |i - j| give the linear kappa, 0.675940. No kappa is a mean of the others: each weighting is its own statistic.'),
  ('appliedai', 'advanced', 'module', 'm01-annotator-agreement', 4, 'With labels 0, 1, 2 and 3, how does the quadratic weighting charge a disagreement of three grades, and what kappa does it give on the Ekene pairs?', '["It charges 3, the gap itself, and the quadratic kappa is then 0.675940", "It charges 9, the square of the gap, and the quadratic kappa is 0.771549", "Its charge is 1, the same as any other disagreement, so kappa stays at 0.579841", "A charge of 6, twice the gap, which brings the quadratic kappa up to 0.771549"]'::jsonb, 1, 'The basis states w = (i - j)^2 on the label positions, and with these labels the positions are the grades, so a three-grade gap costs 9. That weighting gives 0.771549. A charge equal to the gap is the linear weighting, whose kappa is 0.675940. A charge of 1 for every disagreement is the unweighted kappa, 0.579841. No weighting doubles the gap.'),
  ('appliedai', 'advanced', 'module', 'm01-annotator-agreement', 5, 'Why is the Ekene annotators'' kappa higher under linear and quadratic weights than unweighted?', '["The weights raise the observed agreement from 0.721311, since near misses count as partial agreement in it", "Most of their disagreements are one grade apart, 40 of the 51, and chance spreads its disagreements over far pairs too", "Weighted kappa leaves the rows with grade 0 out of the expected agreement, which lowers that denominator", "The weights are fitted to the confusion counts, so they always return a higher kappa than the unweighted one"]'::jsonb, 1, 'Weighting charges a far disagreement more than a near one. These annotators mostly slip by one grade (40 of their 51 disagreements), while chance, working from the margins, produces far disagreements as well, so the weighted ratio of observed to expected disagreement falls and kappa rises. The engine reports the observed and expected agreement unweighted whatever the weighting; no rows are left out; and the weights are stated formulas on the label positions, never fitted.'),
  ('appliedai', 'advanced', 'module', 'm01-annotator-agreement', 6, 'Under linear weights the Ekene figures read observed disagreement 0.338798 and expected disagreement 1.045478. A reviewer calls the second figure impossible. What is the right reply?', '["The reviewer is right: a disagreement is a share of pairs, so the engine should have capped it at 1", "It exceeds 1 because the engine divides by the 51 disagreements where the 183 pairs belong", "The figure is 1 minus a negative expected agreement, which the weights produce on this set", "A weight can exceed 1, so a weighted disagreement can too; only the ratio of the two enters kappa"]'::jsonb, 3, 'Under linear weights a three-grade disagreement is charged 3, so sum w E over n can pass 1; the same holds for the quadratic 2.009257. Kappa uses only the ratio, 1 - 0.338798 / 1.045478 = 0.675940. The engine caps nothing here, divides by n, and reports the expected agreement 0.336708 unweighted in every row, so there is no negative agreement anywhere.'),
  ('appliedai', 'advanced', 'module', 'm01-annotator-agreement', 7, 'Six pairs are rated with the words none, related, relevant and answers, and linear weights are asked for with no labels passed. What does the engine return?', '["A refusal naming `labels`: \"labels must be given in order for linear weights on string ratings (the weights use the label positions)\"", "A kappa computed on the words sorted alphabetically, which puts answers first and none second in the scale", "The unweighted kappa, with a note that the weights were dropped because word ratings carry no order", "A refusal naming `weights`: \"weights must be ''none'', ''linear'' or ''quadratic''\", as words take no weights"]'::jsonb, 0, 'Weights use the label positions, and words have no order of their own: sorting them alphabetically would put "answers" before "none". So the engine refuses, names the field `labels` and says why, in the words quoted. It never guesses an order and never falls back to the unweighted kappa. The `weights` message is for a weighting the engine does not offer, and linear is one it offers.'),
  ('appliedai', 'advanced', 'module', 'm01-annotator-agreement', 8, 'The course''s six stated word-rated pairs are sent with labels none, related, relevant, answers in that order and linear weights. What comes back?', '["A refusal again, because weighted kappa is only offered on number ratings", "The kappa of the Ekene annotators, 0.675940, since the labels match the four grades", "The call runs, and the kappa on the six stated pairs is 0.608696", "0.608696 as the observed agreement, with kappa returned as null and a reason"]'::jsonb, 2, 'Given in order, the labels fix the positions the linear weights use, and the engine returns kappa 0.608696 on the six stated pairs. Word ratings are accepted once their order is stated. 0.675940 is the linear kappa of the 183 Ekene pairs, a different set of ratings. Kappa is null only when both raters give every item the same label, which is not this case, and 0.608696 is the kappa itself.'),
  ('appliedai', 'advanced', 'module', 'm01-annotator-agreement', 9, 'Both raters give every item the grade 2. How does the engine answer a kappa call on those ratings?', '["It returns kappa as null with the reason \"kappa is undefined: both raters gave every item the same label (2), so the expected disagreement is 0\"", "It refuses the call with the field `a` named, since a rater list that holds one single label throughout is not accepted as a set of ratings", "It returns kappa 1, since the two raters agree on every one of the items and so their observed agreement is complete, with no disagreement left to count", "Kappa comes back as 0: the observed and expected agreement are equal, so nothing is gained on chance"]'::jsonb, 0, 'Kappa divides by the expected disagreement, which is 0 when both raters use one and the same label, so the value is undefined. The engine runs the call and returns the result with kappa null and the reason quoted, which is a result with a note and no refusal. It does not substitute 1 or 0 for a ratio it cannot form; a single disagreement anywhere lifts the expected disagreement above 0 and kappa returns.'),
  ('appliedai', 'advanced', 'module', 'm01-annotator-agreement', 10, 'A kappa call passes rater a with three ratings and rater b with two. Which field does the refusal name, and in what words?', '["`a`, with \"a must be a non-empty array of ratings\"", "`labels`, with \"labels[2] repeats 1\", as one label is lost in the check", "The call runs on the first two items and warns of the third", "`b`, with \"b must be an array of 3 ratings, one per item of a\""]'::jsonb, 3, 'The engine reads rater a first and measures rater b against it, so the refusal names `b` and states the length it needed, 3 ratings, one per item of a. The `a` message is for an empty first list. The labels message is for a label listed twice. The engine never trims a list to fit the other: kappa needs one rating from each rater per item.'),
  ('appliedai', 'advanced', 'module', 'm01-annotator-agreement', 11, 'Rater a''s ratings are 0, 3, 1 and the labels are passed as 0, 1, 2. What does the engine return?', '["A kappa with the 3 moved to the nearest label, 2, before the table is built", "A refusal naming `a[1]`: \"a[1] is 3, which is not one of labels\"", "A refusal naming `labels`: the labels must run from 0 to the largest grade given", "The kappa with the 3 left out of the table and a note that one item was dropped"]'::jsonb, 1, 'When labels are passed the engine checks every rating against them, and a 3 that is not among them is refused, the message naming the position `a[1]` and the value. No rating is moved to a neighbour and no item is dropped, because either would change the confusion table without saying so. The labels themselves were valid: nothing requires them to run up to a grade someone typed.'),
  ('appliedai', 'advanced', 'module', 'm01-annotator-agreement', 12, 'A kappa call lists rater a as 0, "related", 2. Which refusal comes back?', '["`labels`: \"labels[2] repeats 1\", for a label that was listed twice", "`a[1]` in the words \"a[1] is 3, which is not one of labels\"", "`a[1]`, with the words \"a[1] must be a finite number, like a[0]\"", "`weights`: \"weights must be ''none'', ''linear'' or ''quadratic''\" in full"]'::jsonb, 2, 'The first rating fixes the kind: a[0] is a number, so a[1] must be a finite number too, and a word there is refused with the message quoted. The repeated-label message needs a labels list with a duplicate in it, and the not-one-of-labels message needs a labels list the rating falls outside; neither was passed. No weighting was asked for, so the weights message cannot arise.'),
  ('appliedai', 'advanced', 'module', 'm01-annotator-agreement', 13, 'The Ekene grades reduced to relevant or not give kappa 0.634430 at grade 1 or more and 0.794115 at grade 2 or more. What does that say about the retrieval metrics'' default threshold?', '["Grade 1 is where the annotators agree best of all, which is exactly why every retrieval metric takes it as the default relevance line", "The two figures are observed agreements and not kappas, so they say nothing about the threshold at all", "The threshold makes no difference to kappa, since both reductions come from one and the same set of 183 judged pairs", "The default, grade 1, sits on the line the annotators agree on less well, so a report states the kappa at the threshold its metrics use"]'::jsonb, 3, 'Kappa at grade 2 or more, 0.794115, is higher than at grade 1 or more, 0.634430, so the annotators separate grade 1 from grade 2 more reliably than grade 0 from grade 1, and the metrics'' default of grade 1 inherits the weaker line. The observed agreements at the two thresholds are 0.814208 and 0.928962; the figures in the question are kappas. The threshold changes the ratings, so it changes kappa.'),
  ('appliedai', 'advanced', 'module', 'm01-annotator-agreement', 14, 'Where did the second annotator''s grades on the 183 Ekene pairs come from?', '["A stated fixture draw: the primary grade moved one grade with probability 0.25 and two grades with probability 0.05, random.Random(20260925)", "A language model asked to grade every judged pair again, with its answers saved once to a file so that each later run would match them exactly", "The engine''s own bootstrap stream on seed 7, which redraws the second set of grades every time a kappa call is made on those pairs", "A second person at the platform who read all 60 passages against all 24 queries and graded each pair"]'::jsonb, 0, 'The fixture record states how the synthetic second grades were drawn, with the probabilities and the seed quoted. No language model wrote or scores any fixture in this course, and a key resting on one would have no fixed answer. The bootstrap is the engine''s only random draw and it never touches the grades. The Ekene data are synthetic, so no person graded anything, and only the 183 pooled pairs carry grades.'),
  ('appliedai', 'advanced', 'module', 'm01-annotator-agreement', 15, 'Numeric grades are passed to the kappa function with the labels left out. How does the engine fix the label order the weights use?', '["The order in which each grade first appears in rater a", "The distinct ratings, sorted ascending, as its basis states", "The grades 0 to 10, the full grade scale the engine will accept", "Descending, so that the highest grade takes position 0"]'::jsonb, 1, 'The basis says labels are the distinct ratings sorted ascending, so the Ekene grades give 0, 1, 2, 3 and the positions equal the grades. Order of appearance would make the weights depend on how the pairs happened to be listed. The accepted grade range belongs to the retrieval metrics and does not set kappa labels. A descending order would still give the same gaps between grades, but it is not the order the engine uses.'),
  ('appliedai', 'advanced', 'module', 'm02-calibration', 1, 'In the Ekene calibration set, when is a row''s outcome 1, and what share of the 200 rows has it?', '["At grade 1 or more, the retrieval default; the base rate is 0.190000", "When the judged grade is 2 or 3; the base rate is 0.190000", "Whenever the probability is at least 0.5, so the base rate is the share above that line", "In system A''s top 5; the base rate is 0.443478"]'::jsonb, 1, 'The fixture defines the outcome as 1 when the judged grade is 2 or 3, which is stricter than the grade 1 default of the retrieval metrics; 0.190000 of the 200 rows have it. An outcome is what happened, so it never comes from the probability. 0.443478 is system A''s mean precision at 5, a retrieval figure with nothing to do with these rows.'),
  ('appliedai', 'advanced', 'module', 'm02-calibration', 2, 'The Brier score of the Ekene rows is 0.168382 at 5, 10 and 15 bins. Why does the bin count leave it unchanged?', '["The engine fixes the bins at 10 for the Brier score whatever count is passed to it", "Every bin on this set is over-confident, so the bins happen to cancel out in the mean", "It is the row-weighted sum of the bin gaps", "It is the mean of (p - y)^2 over the rows, and it uses no bins at all"]'::jsonb, 3, 'The basis gives the Brier score as mean (p - y)^2: each row adds the square of its own miss, and no bin enters. The bin count passed to the call is used for the table, ECE, MCE and the Murphy terms. The over-confidence argument explains why ECE holds still on this set, a different figure. A row-weighted sum of bin gaps is ECE''s definition.'),
  ('appliedai', 'advanced', 'module', 'm02-calibration', 3, 'In how many of the ten bins of the Ekene reliability table is the mean probability above the observed frequency, and what does that make the classifier there?', '["10 of 10: over-confident in every bin", "5 of 10: over-confident in the upper half only", "None of them: under-confident in every bin", "9 of 10: bin 9 alone is under-confident here"]'::jsonb, 0, 'Every bin''s mean probability sits above its observed frequency, from bin 0 (0.065263 against 0.052632) to bin 9 (0.974286 against 0.904762), so the classifier is over-confident in all ten. Bin 9 is the upper bin that comes nearest its promise, with a gap of 0.069524, and it is still over-confident. No bin has its observed frequency above its mean probability.'),
  ('appliedai', 'advanced', 'module', 'm02-calibration', 4, 'Bin 7 of the ten-bin table holds 3 rows at a mean probability of 0.723333, none of them relevant. What does that bin do to ECE and to MCE?', '["It sets ECE, since ECE is the largest gap in any non-empty bin of the table, 0.723333", "Both ignore it: a bin with fewer than 5 rows is treated as empty and skipped by the sums", "It sets MCE outright at 0.723333 and moves ECE little, since 3 of 200 rows weight its gap", "It moves both alike, as each averages the ten gaps with an equal weight for every bin"]'::jsonb, 2, 'MCE is the largest gap over non-empty bins, and bin 7''s 0.723333 is the largest, so MCE is 0.723333. ECE weights each gap by n_k / N, and 3 rows of 200 carry little weight. Only an empty bin is skipped, and ECE is the row-weighted sum; an equal weight per bin is the common alternative the engine did not take.'),
  ('appliedai', 'advanced', 'module', 'm02-calibration', 5, 'How does the engine weight each bin''s gap when it computes ECE, and what alternative did it decline?', '["By one over the number of non-empty bins, so each bin counts equally; it declined weighting by the rows", "By the square of each gap, as the REL term does, to stress the large gaps; it declined the plain mean of the gaps", "By its share of the rows, n_k / N, after Guo et al. (2017); it declined the plain mean of the gaps over bins", "By its mean probability, so the confident bins count most; it declined the weights of Guo et al. (2017)"]'::jsonb, 2, 'The basis says sum over non-empty bins of n_k / N x |observed_k - mean p_k|, the Guo et al. (2017) form, and the course names the unweighted mean over bins as the common alternative, under which a 3-row bin would count as much as a 39-row one. Squared gaps weighted by rows are the reliability term of the decomposition, a different figure. Nothing is weighted by mean probability.'),
  ('appliedai', 'advanced', 'module', 'm02-calibration', 6, 'On the Ekene rows ECE is 0.209300 at 5, 10 and 15 bins while MCE reads 0.660556, 0.723333 and 0.750000. Why does ECE stay put here?', '["Every non-empty bin is over-confident at all three counts, so ECE is the mean probability minus the base rate", "ECE uses no bins, being a mean over rows, exactly like the Brier score beside it in the result", "The engine rounds ECE to the nearest bin width before it reports it, which hides small movements", "ECE is always fixed by the base rate, whatever the set, so a report may quote it with no bin count"]'::jsonb, 0, 'When every bin is over-confident each gap is mean probability minus observed frequency, with no sign to flip, and the row weights add the bins back into 0.399300 - 0.190000 = 0.209300. That is particular to this set: with bins on both sides of the diagonal ECE can move with the bin count, so it is always quoted with its bins. ECE is built from bins, and nothing is rounded.'),
  ('appliedai', 'advanced', 'module', 'm02-calibration', 7, 'What does the rise of MCE from 0.660556 at 5 bins to 0.750000 at 15 bins show?', '["The classifier got worse: the rows were redrawn for each bin count", "An engine fault, because a maximum gap over the same rows cannot depend on where bins are cut", "Rounding: probabilities given to 2 decimals make MCE jump in steps", "Finer bins can isolate a smaller, worse group of rows, so MCE is quoted with its bin count"]'::jsonb, 3, 'The rows are the same 200 at every count; only the bins change. A narrower bin can gather a handful of rows with a large gap that a wider bin would dilute, so the worst gap can grow as bins get finer. That is why the course quotes MCE and ECE with their bin count. Nothing is redrawn, the maximum gap depends on the bins by definition, and no rounding of that kind is applied.'),
  ('appliedai', 'advanced', 'module', 'm02-calibration', 8, 'A calibration call is passed judged grades, 0, 2, 3, as the outcomes. What does the engine return?', '["A result on the grades read as outcomes of 0, 1 and 1 at grade 2 or more", "A refusal naming `yTrue[1]`: \"yTrue[1] must be 0 or 1\"", "A refusal naming `yTrue`: \"yTrue must be a non-empty array of 0 and 1 outcomes\"", "A result with a note that the grades were reduced to 0 and 1 at grade 1 or more"]'::jsonb, 1, 'An outcome must be 0 or 1, and the first value that is neither, the 2 at position 1, is refused with its position named, in the words quoted. The engine never reduces grades to outcomes itself: the threshold is the caller''s to state. The `yTrue` message is for an empty list of outcomes.'),
  ('appliedai', 'advanced', 'module', 'm02-calibration', 9, 'A BM25 score of 2.191027 is pasted in as the second of the probabilities of a calibration call. What comes back, and why?', '["A refusal, \"probabilities[1] must be a number from 0 to 1\": a score is never a probability and can run above 1", "A Brier score computed on the pasted score after the engine has scaled it into 0 to 1 by the largest value given", "The Brier score 0.168382, since the engine reads the calibration probabilities from the fixture", "A refusal naming `bins`, because a score above 1 would need one more bin above the last one to hold it in the table"]'::jsonb, 0, 'The probability check refuses any value outside 0 to 1, naming its position, in the words quoted. A BM25 score is a score and never a probability, and it can exceed 1. The engine rescales nothing, reads the probabilities it is given, and the bins message is for a bin count outside 1 to 100.'),
  ('appliedai', 'advanced', 'module', 'm02-calibration', 10, 'Two outcomes are passed with one probability. Which field does the engine name?', '["`yTrue`, with \"yTrue must be a non-empty array of 0 and 1 outcomes\" for the lost pair", "None: the unmatched outcome is dropped", "`bins`, with \"bins must be a whole number from 1 to 100\", as the rows cannot be binned", "It names `probabilities`: \"probabilities must be an array of 2 numbers, one per outcome\""]'::jsonb, 3, 'The outcomes come first and fix the length, so the probabilities list is measured against them and the refusal names `probabilities`, stating the 2 it needed. The `yTrue` message is for no outcomes at all. The engine never drops an unmatched row. The bins message is for a bin count outside 1 to 100.'),
  ('appliedai', 'advanced', 'module', 'm02-calibration', 11, 'A calibration call asks for 101 bins, and a second asks for 1. What does the engine do with each?', '["It runs both, capping 101 at 100 bins and reporting 1 bin as a one-line table with every one of the rows in bin 0", "It refuses both, since the bin count must lie strictly between 1 and 100, both ends excluded", "It refuses 101 with \"bins must be a whole number from 1 to 100\" and runs 1, putting every row in one bin", "It runs 101 with a note that the extra bin is empty and refuses 1 as too coarse to resolve"]'::jsonb, 2, 'The bin count is a whole number from 1 to 100, both ends accepted, so 101 is refused with the words quoted and 1 is run. One bin puts every row in a single bin; the decomposition module shows it cannot resolve anything. The engine never caps a value silently or adds a note in place of a refusal, and 1 is a valid count.'),
  ('appliedai', 'advanced', 'module', 'm02-calibration', 12, 'Where do the probabilities in the Ekene calibration set come from?', '["The engine''s own relevance classifier, fitted on the 183 judged pairs each time a calibration call runs", "A stated curve on the BM25 score, 1 / (1 + exp(-(0.6 x bm25 - 3.0))), rounded to 2 dp and fitted elsewhere", "A language model asked how likely each passage is to answer its query, with the replies saved to the file", "The TF-IDF cosine of each passage, which already lies between 0 and 1 and so serves as a probability"]'::jsonb, 1, 'The fixture states the curve and says it was fitted elsewhere, so it is not calibrated here. The engine reads no probability of its own: the probabilities are given inputs, and fitting a classifier is the machine learning course''s subject. No model output enters any fixture. A cosine is a score, and a score is never a probability even when it lies between 0 and 1.'),
  ('appliedai', 'advanced', 'module', 'm02-calibration', 13, 'Bin 6 of the ten-bin table holds 15 rows at a mean probability of 0.648000 with an observed frequency of 0.000000. How is that bin read?', '["The classifier gave 15 rows a mean of 0.648000 and none of them was relevant: a gap of 0.648000", "The bin counts as empty, since no outcome in it is 1, so its means are null and ECE skips it", "Its gap is 0.000000, since an observed frequency of 0 leaves nothing to compare in the bin", "Its 15 rows are left out of ECE, as a bin with no relevant row in it cannot be calibrated at all"]'::jsonb, 0, 'The rows column says 15 rows fell in bin 6, and their mean probability, 0.648000, promised a good share of relevant rows; none was, so the gap is 0.648000. An empty bin is one with no rows, and only such a bin is skipped. An observed frequency of 0 is a real frequency, and the bin enters ECE with its row weight.'),
  ('appliedai', 'advanced', 'module', 'm02-calibration', 14, 'A classifier gives every Ekene row the base rate, 0.190000. What would a reliability table show, and why would it still be no use?', '["Ten bins with equal rows, each one over-confident by the base rate, so that the gaps add to exactly 0.190000", "An error, since the engine refuses any probability list in which every single value given is equal to every other value", "A perfect score in every bin, which would make it the very best classifier that the Ekene calibration set can reward", "One populated bin, its gap 0 up to rounding: honest about the average, and it separates no relevant row from any other"]'::jsonb, 3, 'Every row lands in the one bin holding the base rate, whose observed frequency is the base rate itself, so the one gap is 0 up to rounding: the mean of the 200 equal probabilities lands a few bits away from the observed frequency, so the gap prints 0.000000 without being exactly 0, and printed alike is not equal. Calibration and separation are different properties: this classifier gives every row the same number, so it cannot rank relevant rows above the others. The engine accepts equal probabilities, and a zero gap is no evidence of usefulness.'),
  ('appliedai', 'advanced', 'module', 'm02-calibration', 15, 'How does the engine place a row whose probability is exactly 1 at 10 bins?', '["In a bin 10 above the table, made for the one row", "In bin 9, because 1 closes the last bin", "Nowhere: a probability of 1 is refused as out of range", "In bin 9 or bin 10, by the id ascending tie rule"]'::jsonb, 1, 'The bin rule is i/10 <= p < (i+1)/10 with the last bin closed at 1, so a probability of 1 has a home in bin 9 and there is no bin above it. A probability from 0 to 1 is accepted, both ends included. The id tie rule belongs to the ranking and plays no part in binning.'),
  ('appliedai', 'advanced', 'module', 'm03-decomposing-the-brier-score', 1, 'Which identity does the engine close on the Ekene calibration set, and with what terms at 10 bins?', '["Brier = REL + RES - UNC, the three classic terms alone: 0.080032 + 0.064570 - 0.153900 leaves the rest to rounding", "Brier = REL - RES + UNC: 0.080032 - 0.064570 + 0.153900, which is 0.169362 and matches the score once rounded", "Brier = REL - RES + UNC + WBV - 2 WBC, taking the engine''s 0.001669 and doubling it before it is subtracted", "Brier = REL - RES + UNC + WBV - WBC: 0.080032 - 0.064570 + 0.153900 + 0.000689 - 0.001669 = 0.168382"]'::jsonb, 3, 'The basis states Brier = REL - RES + UNC + WBV - WBC after Stephenson, Coelho and Jolliffe (2008) eq. 7, and the five figures sum to 0.168382, the Brier score, with a closure of -8.33e-17. The three classic terms give 0.169362, which is a different number from 0.168382 at six decimals and does not match. The engine''s WBC already carries the paper''s factor 2, so doubling it again breaks the identity. Resolution enters with a minus sign and uncertainty with a plus.'),
  ('appliedai', 'advanced', 'module', 'm03-decomposing-the-brier-score', 2, 'REL - RES + UNC on the Ekene rows at 10 bins is 0.169362, and the Brier score is 0.168382. What accounts for the difference?', '["Rounding in the last bits of a double, which the closure of -8.33e-17 reports", "The two within-bin terms, WBV and WBC, which the three classic terms leave out", "The 17 rows on an interior bin edge, which the classic terms place in the lower bin", "Log loss, which the calibration call adds to the classic terms before it reports"]'::jsonb, 1, 'Reliability and resolution treat every row in a bin as if it carried the bin''s mean probability. WBV and WBC account for the spread inside each bin, and with them the sum is exactly the Brier score. The closure measures the gap left after all five terms, which is -8.33e-17; the gap here is about a thousandth. The engine''s bin rule opens the upper bin for every term, and log loss is a separate figure.'),
  ('appliedai', 'advanced', 'module', 'm03-decomposing-the-brier-score', 3, 'Uncertainty on the Ekene rows is 0.153900. What sets it, and can a better classifier lower it?', '["Only the outcomes: base rate x (1 - base rate) = 0.190000 x 0.810000; no classifier can change it", "Bin choice: it is the spread of observed frequencies across bins, so choosing finer bins can lower it", "Probability spread: it is their variance, so a classifier that spreads them further lowers it", "The worst bin: it is MCE squared, so fixing bin 7 would bring the uncertainty term down"]'::jsonb, 0, 'UNC = base rate (1 - base rate), and the base rate is the share of outcomes that are 1, so the term belongs to the outcomes alone and stays 0.153900 whatever the classifier or the bin count. The spread of observed frequencies around the base rate is resolution. The spread of the probabilities inside bins is WBV. MCE plays no part in the decomposition.'),
  ('appliedai', 'advanced', 'module', 'm03-decomposing-the-brier-score', 4, 'Every Ekene row is put in one bin. What do reliability and resolution become?', '["Both become 0.000000, because a single bin has nothing to compare its rows against", "RES becomes 0.153900, the uncertainty, and REL 0.000000, since one bin is calibrated", "RES is 0.000000 and REL is 0.043806, the squared gap between the mean probability and the base rate", "The call is refused: a decomposition needs at least two bins to separate the rows"]'::jsonb, 2, 'With one bin the observed frequency is the base rate itself, so resolution, the spread of bin frequencies from the base rate, is 0: one bin cannot resolve anything. Reliability becomes (mean probability - base rate)^2 = 0.043806, a test of the average only. The bin count runs from 1 to 100, so one bin is accepted.'),
  ('appliedai', 'advanced', 'module', 'm03-decomposing-the-brier-score', 5, 'Six stated rows, probabilities 0.61, 0.62, 0.64, 0.66, 0.68 and 0.69 with outcomes 1, 0, 1, 0, 1, 1, all fall in bin 6. Their pooled within-bin covariance is 0.003333. What WBC does the engine return?', '["0.003333, since WBC is the pooled within-bin covariance itself and the identity itself is what doubles it", "0.006667, twice the pooled covariance, as WBC carries the factor 2 of the paper''s fifth term", "0.000867, since WBC measures how widely the six stated probabilities spread about their bin mean", "The pooled covariance halved, as the six rows are split between two outcomes"]'::jsonb, 1, 'Stephenson, Coelho and Jolliffe (2008) write the fifth term of eq. 7 as -(2/N) sum (y - observed_k)(p - mean p_k) and name it -WBC, so WBC is twice the pooled within-bin covariance: 2 x 0.003333 = 0.006667, the engine''s figure, with a closure of 0. Quoting the covariance as WBC is a real wrong method, and the identity then fails to close. 0.000867 is WBV on these rows. Nothing halves the covariance.'),
  ('appliedai', 'advanced', 'module', 'm03-decomposing-the-brier-score', 6, 'In the engine''s identity Brier = REL - RES + UNC + WBV - WBC, where is the factor 2 of Stephenson, Coelho and Jolliffe''s eq. 7 fifth term?', '["In front of WBC: the engine''s identity reads - 2 WBC and applies the 2 to its reported 0.001669 each time", "Inside WBV: the fourth term carries it, and WBC is left as the pooled within-bin covariance without any factor", "Nowhere at all, because the pooled within-bin covariance never needs a factor for the Brier identity to close", "Inside WBC: the paper names the whole fifth term -WBC, so WBC is twice the pooled within-bin covariance"]'::jsonb, 3, 'The line after eq. 7 names the five components BS = REL - RES + UNC + WBV - WBC, and the fifth component written out is -(2/N) sum (y - observed_k)(p - mean p_k), so the 2 belongs to WBC as the paper labels it. The engine''s WBC is the paper''s, and the identity has no further 2. WBV is sum (p - mean p_k)^2 / N with no factor. Drop the 2 and the identity no longer closes.'),
  ('appliedai', 'advanced', 'module', 'm03-decomposing-the-brier-score', 7, 'On the six stated rows in bin 6, WBV is 0.000867. What does that term measure?', '["How far the bin''s mean probability, 0.650000, sits from its observed frequency", "The covariance of outcomes with probabilities in the bin, before its factor of 2", "The spread of the probabilities inside the bin, sum (p - mean p_k)^2 / N", "The spread of the outcomes inside the bin about the observed frequency, 0.666667"]'::jsonb, 2, 'The basis gives WBV = sum (p - mean p_k)^2 / N, the within-bin variance of the probabilities; on the six rows the squared deviations from 0.650000 give 0.000867. The distance of a bin''s mean probability from its observed frequency is what reliability squares and weights. The covariance of outcome with probability is what WBC carries, twice over. The outcomes'' own spread enters no term by that name.'),
  ('appliedai', 'advanced', 'module', 'm03-decomposing-the-brier-score', 8, 'The calibration call returns a closure of -8.33e-17 for the Ekene rows at 10 bins. How is that figure read?', '["The five terms and the Brier score agree up to rounding in the last bits of a double", "A small negative bias in the Brier score, to be added back to the score before it is quoted", "The within-bin covariance term, which the engine reports under a second name here", "Evidence that a term is wrong, since an exact identity should give 0.000000 flat"]'::jsonb, 0, 'The closure is the Brier score minus the five-term sum, 0 up to rounding. A figure near 1e-16 is floating-point noise and says the terms agree with the score; one the size of a term would say a term was wrong. Nothing is added back to the Brier score, and WBC is reported as its own term, 0.001669.'),
  ('appliedai', 'advanced', 'module', 'm03-decomposing-the-brier-score', 9, 'At 10 bins a probability of exactly 0.3 falls on the edge between bins 2 and 3. Where does the engine put it, and where would scikit-learn''s calibration_curve?', '["Both put it in bin 3, since the two tools share numpy histogram''s rule for edges", "The engine puts it in bin 2, closing the lower bin; the library puts it in bin 3", "Each splits it, half a row to bin 2 and half a row to bin 3, so no bin is favoured", "The engine opens the upper bin, bin 3; the library puts it in the lower bin, bin 2"]'::jsonb, 3, 'The bin rule is i/M <= p < (i+1)/M with the edges as computed in double precision, so an interior-edge value opens the upper bin: bin 3. scikit-learn''s calibration_curve puts it in the lower bin. The engine''s rule is numpy histogram''s; the library''s is the other convention. No tool splits a row between bins.'),
  ('appliedai', 'advanced', 'module', 'm03-decomposing-the-brier-score', 10, 'How many Ekene probabilities sit exactly on an interior edge at 10 bins, and how many of the ten bins change their row count under the library rule?', '["17 probabilities, with the values 0.1, 0.2, 0.3, 0.4 and 0.6; 6 of the 10 bins hold a different count", "5 probabilities, one on each of the edge values; only bin 7 holds a different count between rules", "None, since probabilities to 2 decimals never meet an edge computed in double precision exactly", "17 probabilities, all at 0.5; every one of the 10 bins holds a different number of rows as a result"]'::jsonb, 0, 'The course counted 17 edge probabilities over the whole set, with the values 0.1, 0.2, 0.3, 0.4 and 0.6, and derived the library rule''s table: 6 of the 10 bins hold a different number of rows. Bin 7 is one of the bins that keeps its count, holding no edge value. A value typed as 0.3 is compared with the double 3/10 and does meet it. No edge value is 0.5 on this set.'),
  ('appliedai', 'advanced', 'module', 'm03-decomposing-the-brier-score', 11, 'On the Ekene rows the library rule gives REL 0.078849 against the engine''s 0.080032, while ECE and MCE agree. Why does MCE agree?', '["MCE uses no bins, being a mean over rows like the Brier score, so no edge rule can ever move it", "The largest gap is in bin 7, which holds no edge value, so moving the edge rows cannot touch it", "The library rule rescales the gaps so that the worst one always matches under either rule", "Every bin is over-confident, so the maximum of the gaps is fixed by the mean probability"]'::jsonb, 1, 'MCE is the largest gap over non-empty bins, and on this set it is bin 7''s 0.723333 under both rules because bin 7 holds no edge value. The over-confidence argument explains why ECE agrees: moving an edge row between two over-confident bins leaves the pooled gap unchanged. MCE is built from bins, and no rule rescales gaps. REL differs, by -1.18e-3, so the rule is named whenever tables are compared.'),
  ('appliedai', 'advanced', 'module', 'm03-decomposing-the-brier-score', 12, 'Log loss on the Ekene rows is 0.503184 with 5 probabilities clipped. Where does the figure come from?', '["From a copy of the formula kept inside the evaluation engine itself, clipped at eps 1e-15", "From the Brier score, since log loss is simply its natural logarithm on the same rows", "From engines/dataai/ml.js logLoss, imported and called on the same rows, eps 1e-15", "From the bins: the mean of -ln of each bin''s gap, taken over the non-empty bins"]'::jsonb, 2, 'The calibration call imports logLoss from the machine learning engine and calls it on the same rows; the course checked the figure is exactly what that function returns. One definition on the platform means one answer, so the evaluation engine keeps no copy. Log loss is -(1/n) sum [y ln p + (1 - y) ln(1 - p)] on the rows and uses no bins.'),
  ('appliedai', 'advanced', 'module', 'm03-decomposing-the-brier-score', 13, 'Why does the log loss function clip every probability into [eps, 1 - eps] before taking logarithms?', '["A probability of exactly 0 or 1 would make the logarithm infinite for a row that went the other way", "To keep log loss below 1 on every set, so it reads on the same scale as the Brier score does", "To round the probabilities to 2 decimals, as the calibration set''s fixture record states them", "So that probabilities exactly on an interior bin edge move off the edge into the lower bin"]'::jsonb, 0, 'ln 0 is minus infinity, so a row given 0 that turns out relevant, or 1 that turns out not, would make the mean infinite. Clipping at eps 1e-15 sets a large finite cost instead, and the Ekene set has 5 such probabilities clipped. Log loss can exceed 1 after clipping; the fixture''s rounding happened when the file was written; and log loss uses no bins.'),
  ('appliedai', 'advanced', 'module', 'm03-decomposing-the-brier-score', 14, 'A calibration call passes eps 0.5. What happens?', '["Every probability is clipped to 0.5, and log loss is reported as ln 2", "The engine ignores eps, since it has no log loss of its own to pass on", "A refusal naming `bins`, since eps also sets the width of the bins", "A refusal naming `eps`: \"eps must be a number above 0 and below 0.5\""]'::jsonb, 3, 'The calibration call passes eps straight to the imported logLoss, which refuses 0.5 with the field `eps` named, in the words quoted: at 0.5 every probability would be clipped to 0.5. The engine does pass eps through; it does not ignore it. eps has nothing to do with the bins.'),
  ('appliedai', 'advanced', 'module', 'm03-decomposing-the-brier-score', 15, 'Inside one bin, the rows with the higher probabilities are more often the relevant ones. What sign does WBC take, and how does it move the Brier score?', '["WBC is negative, and entering with a minus sign it raises the Brier score further still", "WBC is positive, and entering the identity with a minus sign it lowers the Brier score", "WBC is 0, since the bin''s mean probability already accounts for every row within the bin", "WBC is positive, and entering with a plus sign it raises the Brier score by that amount"]'::jsonb, 1, 'WBC is 2 sum (y - observed_k)(p - mean p_k) / N: when higher probabilities go with outcomes of 1 inside a bin the products are positive on balance, so WBC is positive, and the identity subtracts it. Ranking well inside a bin lowers the Brier score. The bin mean ignores the spread, which is exactly what WBV and WBC restore; WBC enters with a minus sign.'),
  ('appliedai', 'advanced', 'module', 'm04-judged-sets-and-leakage', 1, 'How was the Ekene judged set built, and what grade does a passage outside it carry?', '["Every passage in the top 5 of either system was judged, plus the assessor''s additions; an unjudged passage counts as grade 0", "Every one of the 60 passages was judged against every query, so no passage is ever unjudged in any ranked list", "Passages were drawn at random for judging with the bootstrap seed; an unjudged passage is left out of every metric", "The top 10 of BM25 alone was judged, since system A retrieves by BM25; an unjudged passage is scored as grade 1"]'::jsonb, 0, 'The fixture states the pooling rule: the top 5 of both systems at default settings, plus passages the assessor added, and unjudged passages count as grade 0. That is a pool, 183 judged pairs, far fewer than every passage against every query. No random draw chose the pairs, the engine does not drop unjudged passages, and grade 0 credits nothing, where grade 1 would count them as relevant.'),
  ('appliedai', 'advanced', 'module', 'm04-judged-sets-and-leakage', 2, 'At k 5, how many unjudged passages do systems A and B retrieve on the Ekene queries, and why?', '["80 for A and 16 for B, as each system fills its lists from outside the pool", "0 each: the engine refuses to rank a passage that nobody has judged", "0 each: the pool was built from both systems'' own top 5 lists", "16 each: the assessor''s additions sit outside the lists of both systems"]'::jsonb, 2, 'The judged set was pooled from the two systems'' top 5, so every passage either shows at k 5 carries a grade and unjudgedRetrieved is 0 for both. The engine ranks any passage with a score above 0, judged or not; it simply counts the unjudged ones. 80 and 16 are the unjudged counts of two runs the pool did not come from, BM25 at k 10 and BM25 with b 0.4 and the stop list on.'),
  ('appliedai', 'advanced', 'module', 'm04-judged-sets-and-leakage', 3, 'BM25 at k 10 brings 80 unjudged passages into its lists, on 22 of the 24 queries, and its mean precision falls to 0.291304. What can be said of that fall?', '["It is all real, since grade 0 means an assessor read each of those passages and judged it not relevant to the query", "Part may be real and part an artefact: each unjudged passage scores as grade 0 although some may answer their query", "It is all an artefact, so the right precision at 10 is the precision at 5 of the same run, which is 0.443478", "None, since a cutoff of 10 lies outside the judged set and every metric is returned as null with the reason"]'::jsonb, 1, 'Precision at 10 divides by 10, and 80 of the new places hold passages nobody judged, each scored as grade 0. Some may answer the query and count as misses only because nobody looked, so the fall mixes real and artefact and cannot be split from the table. An unjudged grade 0 is no assessor''s verdict, the precision at 5 answers a different cutoff, and the engine returns every metric at k 10.'),
  ('appliedai', 'advanced', 'module', 'm04-judged-sets-and-leakage', 4, 'A new run, BM25 with b 0.4 and the stop list on at k 5, retrieves 16 unjudged passages on 11 queries and scores MAP 0.656854 against system A''s 0.600278. What does the course conclude?', '["It is the better retriever, since it wins on MAP although its 16 unjudged passages all count against it", "Its figures are void, as the engine returns a null MAP for any run with an unjudged passage in its list", "It ties with system A, since its mean precision at 5 is the same 0.443478 and precision is the key figure", "On the judged passages it ranks the relevant ones higher; its standing once the 16 are judged is open"]'::jsonb, 3, 'The table can say that, on the passages the pool judged, the new run places the relevant ones higher on average; it cannot say how the run would score if its 16 unjudged passages were judged. Judging them can raise or lower its figures, and the other systems'' too, so no verdict is final. The engine scores the run and counts the unjudged passages, and a mean precision at 5 that prints alike, 0.443478, is neither a tie nor evidence about the order: printed alike at six decimals is not equal.'),
  ('appliedai', 'advanced', 'module', 'm04-judged-sets-and-leakage', 5, 'Which way does pooling bias tilt a comparison between a new system and the systems the pool was built from?', '["Toward the new system, because its unjudged passages are left out of its denominators and so raise its precision", "Neither way on average, because an unjudged passage is as likely to be relevant as irrelevant, so it cancels out", "Toward whichever system retrieves the shorter lists, since unjudged passages only appear at the foot of long lists", "Toward the pooled systems: they never meet an unjudged passage at the pooled cutoff, and a new system is marked down for good passages the pool never saw"]'::jsonb, 3, 'Every unjudged passage counts as grade 0. A pooled system shows only judged passages at its pooled cutoff, so it is never penalised for one, while a new system that finds good unseen passages is charged for each. That is pooling bias, and it favours the systems the pool came from. Unjudged passages stay in every denominator, nothing makes them cancel, and list length is not the mechanism.'),
  ('appliedai', 'advanced', 'module', 'm04-judged-sets-and-leakage', 6, 'What does the course ask of any report that scores a system the pool was not built from?', '["Drop every query on which the new system retrieved an unjudged passage, then compare the systems on the queries left over", "Report unjudgedRetrieved beside every score, and judge the unjudged passages before comparing it with the pooled ones", "Score the new system at grade 2 or more, where unjudged passages matter less, and compare them at that threshold", "Rescore the pooled systems at k 10 so that they meet unjudged passages too, then compare all four runs just as they stand"]'::jsonb, 1, 'The count of unjudged retrieved passages tells a reader how much of a score rests on assumed zeros, and judging those passages removes the assumption. Dropping queries changes the question and hides the problem. A higher threshold still scores every unjudged passage as grade 0. Pushing the pooled systems outside the pool adds unjudged passages to every run without judging any of them.'),
  ('appliedai', 'advanced', 'module', 'm04-judged-sets-and-leakage', 7, 'Scored at k 5 and grade 1 against the second annotator''s grades instead of the primary ones, which system has the higher mean nDCG?', '["System A, 0.718064 against B''s 0.701037, where on the primary grades B leads, 0.764137 against 0.762753", "System B on both keys: 0.764137 on the primary grades, 0.701037 on the second annotator''s, so the order holds", "Neither: on the second annotator''s grades every query is excluded, so both means are returned as null", "System A on both keys: 0.762753 on the primary grades and 0.718064 on the second, so A leads throughout"]'::jsonb, 0, 'Under the second annotator A''s mean nDCG is 0.718064 and B''s 0.701037; under the primary grades B''s 0.764137 is above A''s 0.762753. The order flips when the key changes and nothing else does. Under the second annotator no query is excluded, so 24 queries enter the means. Each distractor misreads one of the four figures.'),
  ('appliedai', 'advanced', 'module', 'm04-judged-sets-and-leakage', 8, 'Why do 24 queries enter the means under the second annotator''s grades, where the primary grades give 23?', '["Q24 is zeroed under a second key in place of being excluded, as the zero rule asks", "The second annotator judged one extra query, Q25, which the primary grades never covered", "Under the second annotator no query is excluded: some Q24 passage reaches grade 1 or more", "The means are over all queries whatever the key, and 23 was a count of the queries answered"]'::jsonb, 2, 'The no-relevant rule excludes a query with no judged passage at grade 1 or more. On the primary grades that is Q24; under the second annotator no query is excluded, so Q24 has a passage at grade 1 or more there and enters the means. The default rule is exclude, whatever the key; there are 24 queries, Q01 to Q24; and 23 is the number of included queries.'),
  ('appliedai', 'advanced', 'module', 'm04-judged-sets-and-leakage', 9, 'On nDCG, system A and system B differ by less than two hundredths under either key, while switching keys moves each system by more than four hundredths. What rule does the course draw?', '["The second annotator is wrong, since the primary grades came first and the key is fixed at the start", "The larger of the two means decides the verdict, whichever key it was computed on at the time", "A difference between two systems smaller than the difference between two annotators is no finding", "Average the two keys'' figures and report the system with the higher mean nDCG as the winner"]'::jsonb, 2, 'When the key itself moves each system further than the systems differ, the comparison is inside the noise of judging, and the course says so in those words. Neither annotator is privileged: the second set was drawn as a check. Picking the larger mean or averaging keys hides the flip. The paired bootstrap, seed 7, 2000 replicates, level 0.95, reaches the same verdict: its interval for the difference runs from -0.068015 to 0.058726.'),
  ('appliedai', 'advanced', 'module', 'm04-judged-sets-and-leakage', 10, 'Each of the 24 reference answers is scored as a short answer against itself. What does the engine return, and what follows for a test set?', '["24 exact matches of 24, so a leaked key scores perfectly and has to be prevented by process", "23 of 24, since Q24''s empty reference cannot match itself, which reveals a leak on that query", "An error, since the engine refuses a prediction that is textually identical to its truth string", "24 of 24, and the groundedness check then flags every one of them as an unsupported claim"]'::jsonb, 0, 'Each reference normalises to itself, so all 24 match, including Q24, whose empty answer against an empty reference scores exact 1. That is the score a system earns if the key reached it, whatever it can do, and no score can tell a leaked key from skill. So the queries and references are kept out of every prompt, example and fine-tuning set. The engine accepts identical strings, and groundedness checks cited passages, which a reference alone does not have.'),
  ('appliedai', 'advanced', 'module', 'm04-judged-sets-and-leakage', 11, 'System A scores 20 exact matches of 24 and system B 13. A third system whose instructions contained the reference answers would score what, and what would the score say about it?', '["24 of 24, and the engine would flag it, since a perfect score is refused as a sign of leakage", "About 20, like A, because the leak only helps on the queries that A already answers correctly", "A null score with the reason, since exact match is undefined once the key is in the prompt", "24 of 24, and nothing in the score would mark the difference between a leaked key and skill"]'::jsonb, 3, 'A system that returns the key compares perfectly against it, so it scores 24 of 24 and beats both fixed systems. The score only compares an answer with a reference, so it cannot detect how the answer was obtained, and the engine has no leak check and refuses nothing for a perfect score. The leak helps on every query, and exact match is defined for any pair of strings.'),
  ('appliedai', 'advanced', 'module', 'm04-judged-sets-and-leakage', 12, 'A document restating a reference answer word for word is added to the corpus, and a system retrieves it, cites it and copies the figure. How do the groundedness and exact-match checks treat that answer?', '["Groundedness flags it, since a claim copied from a passage is marked unsupported by the check", "Both pass it: the figure is in a cited, retrieved passage, and it matches the reference", "Exact match fails it, since a reference that appears in the corpus is removed before scoring", "Both refuse it, since a passage that restates a reference is not accepted in a corpus at all"]'::jsonb, 1, 'Groundedness asks only whether the claim appears in a passage the answer cites and retrieved, which it does; grounded is a statement about the passage and says nothing of how the figure came to be there. Exact match compares normalised strings, and they are equal. The engine removes nothing and refuses no passage for its content, which is why a leak through the corpus has to be stopped by process.'),
  ('appliedai', 'advanced', 'module', 'm04-judged-sets-and-leakage', 13, 'Q10 "diesel spill during bunkering" has only 3 judged passages. Why so few, when the pool takes the top 5 of each system?', '["The pool took the top 5 of each system, and both lists overlap exactly, leaving 3 distinct passages to judge", "Only 2 passages contain a query word, so neither system ranks more than 2; the third came from the assessor", "Two of the five pooled passages were duplicates, EKD-046 and EKD-058, and were judged only once between them", "The assessor removed the passages that scored 0, which left 3 of the 10 pooled passages judged"]'::jsonb, 1, 'Only a score above 0 is ranked, and only 2 passages contain a word of the query, so each system''s list holds 2 passages although k is 5. The pool therefore adds just those 2, and the third judged passage came from the assessor''s additions. EKD-046 and EKD-058 are those 2 passages, each judged in its own right, and nobody removes a judged passage.'),
  ('appliedai', 'advanced', 'module', 'm04-judged-sets-and-leakage', 14, 'Under the primary grades, Q24 "subsea tree replacement on Ekene-5" has 8 judged passages. What does the engine say when it computes nDCG for system A on Q24?', '["A refusal naming `judgments`, because a judged query must hold at least one passage at grade 1 or more to be scored", "nDCG 0.000000, since system A retrieves no relevant passage for Q24 and so its DCG and nDCG are both 0", "nDCG is returned as null with the note \"nDCG is undefined: the query has no judged documents, so the ideal DCG is 0\"", "nDCG is returned as null with the note \"nDCG is undefined: the 8 judged documents all have grade 0, so the ideal DCG is 0\""]'::jsonb, 3, 'Q24''s 8 judged passages all carry grade 0, so the ideal DCG is 0 and nDCG is returned as null with the note that names this case, quoted. The other wording is for a query with no judged documents at all, which Q24 is not. A query nothing answers is a result with a note and no refusal, and 0 over 0 is undefined, never 0.'),
  ('appliedai', 'advanced', 'module', 'm04-judged-sets-and-leakage', 15, 'How many planted defects does the Ekene fixture record list, and what happens to the build if the engine fails to find one?', '["22 items; the build fails if any one of them is not found", "22 items; any defect not found is dropped from the list", "11 items, one per unsupported claim of system B''s answers", "24 items, one per query; a missed one is logged and passed"]'::jsonb, 0, 'The fixture tables 22 planted items, each with the engine behaviour that finds it, and the course states that the build fails if any is not found. Nothing is dropped quietly. 11 is the count of system B''s unsupported claims, one kind of planted evidence among several, and the defects are not one per query.'),
  ('appliedai', 'advanced', 'module', 'm05-boundaries-ties-and-caps', 1, 'Passages n2 "oil water" and n1 "oil water gas" are scored by BM25 for "oil" with b = 1e-7, and both scores print 0.470004 at six decimals. How does the engine order them?', '["n1 above n2: the two scores tie at six decimals, and so the tie goes to the id ascending", "n2 above n1: the scores differ by 1.28e-8, which the 12-digit key sees, so they do not tie", "n1 above n2, with a tie reported, since any BM25 scores that print alike are treated as equal", "Either order, since the engine keeps the input order for any two scores that print the same"]'::jsonb, 1, 'Two scores tie only when they agree to 12 significant digits, and the keys are 0.470003629246 and 0.470003616427, so there is no tie and n2 ranks above n1 on its score. Printed alike is not equal: six decimals hide a difference the key sees. With ids alone n1 would come first, which is exactly what the engine does not do here. Input order never decides.'),
  ('appliedai', 'advanced', 'module', 'm05-boundaries-ties-and-caps', 2, 'Why does the engine compare scores through a 12-significant-digit key and decline a relative tolerance?', '["A tolerance is slower to compute on large corpora, and the key was chosen to keep a ranking of 5000 passages fast enough", "The key rounds every score to six decimals first, so it matches the printed figures and a reader can check any tie", "A relative tolerance would tie the two copies EKD-046 and EKD-058, while the key keeps them apart by their ids", "A key is transitive: equal keys tie, full stop, while a tolerance can make a near b and b near c with a far from c, which breaks a sort"]'::jsonb, 3, 'The course''s stated reason is transitivity: a key partitions the scores into tie groups, while a tolerance can chain near neighbours into a group whose ends are not near, and a sort cannot handle that. The key uses 12 significant digits, far finer than the six decimals printed. EKD-046 and EKD-058 do tie under the key, and the id ascending then orders them. Speed is not the reason given.'),
  ('appliedai', 'advanced', 'module', 'm05-boundaries-ties-and-caps', 3, 'What does the 12-digit key absorb that a direct comparison of two doubles would not?', '["Differences in passage length, which b already normalises away before any tie is ever tested", "Any gap too small to show at six decimals, so that every pair of scores printing alike is a tie", "Last-bit differences that arise when the terms of equal texts are added in a different order", "Unicode case differences in two copies of a passage, which the tokeniser keeps apart"]'::jsonb, 2, 'A score is a sum of floating-point terms, and two passages with the same text can land a few bits apart when the terms are summed in another order. The key rounds that away, so a difference the key still sees is a real difference in the inputs. It does not tie scores that merely print alike, as the n1 and n2 pair shows, and it knows nothing of lengths or text.'),
  ('appliedai', 'advanced', 'module', 'm05-boundaries-ties-and-caps', 4, 'Q10 is ranked by BM25 at k 1. EKD-046 and EKD-058 both score 13.884966. What does the engine return?', '["EKD-046, with tieAtCutoff true: the cut falls inside the tie and the id ascending decided", "EKD-058, since the later copy of a duplicated passage is kept and the earlier one dropped", "Both passages, since a tie at the cutoff lengthens the list beyond k to hold the tied group", "EKD-046, with tieAtCutoff false: the two passages are equal, so no tie needs reporting"]'::jsonb, 0, 'The two copies carry the same text and the same score, so they tie; the id ascending puts EKD-046 first, and at k 1 the cut falls between the tied pair, which the engine flags with tieAtCutoff true. The list never grows past k. A tie is reported whenever it exists, and tieAtCutoff is what says the id alone decided which passage stayed.'),
  ('appliedai', 'advanced', 'module', 'm05-boundaries-ties-and-caps', 5, 'System B''s extraction prediction 45.25 for the label 45.2 on EKD-032 sits on the absTol 0.05. How is the cell scored, and by which boundary rule?', '["Wrong: every limit in the engine is exclusive, so a difference lying exactly on the tolerance fails", "Missed: a value on the tolerance edge is treated as empty, and so the label value goes unmatched", "Wrong: the double difference is above 0.05 here, as it was for the 64.7 on EKD-033", "Correct: a number matches when |prediction - label| <= max(absTol, relTol x |label|), inclusive"]'::jsonb, 3, 'The extraction number rule is inclusive, and the course states the double computes this difference as just under 0.05, so the cell is correct. Boundaries are per rule, never global: some rules include their limit and some exclude it. A value on the edge is still a value, and 64.7 against 64.6 on EKD-033 is wrong because its difference is above 0.05.'),
  ('appliedai', 'advanced', 'module', 'm05-boundaries-ties-and-caps', 6, 'In the paired bootstrap, how is a replicate whose A minus B difference is exactly 0 counted in the share at or below 0?', '["It is counted, because \"a does not beat b\" includes a draw", "It is dropped from both counts, being neither a win nor a loss", "It is split, half counted in the share and half counted out", "It is counted out, since only a strictly negative one counts"]'::jsonb, 0, 'The share is the share of replicates with a difference at or below 0, and the boundary table states that a replicate exactly 0 is counted; only replicates above 0 are not. No replicate is dropped or split. The share at or below 0 for nDCG, seed 7 and 2000 replicates, is 0.511000, and it is a count of replicates, which the engine does not call a p-value.'),
  ('appliedai', 'advanced', 'module', 'm05-boundaries-ties-and-caps', 7, 'A bootstrap call asks for level 0.5. What does the engine return?', '["A 50 percent interval, read from the middle half of the bootstrap means", "A refusal naming `level`: \"level must be 0.8, 0.9, 0.95 or 0.99\"", "The 0.95 interval, the default, with a note that 0.5 was not one of the levels", "A refusal naming `nBoot`, since level 0.5 needs more replicates to be read"]'::jsonb, 1, 'The engine accepts four levels and refuses every other, naming the field `level`, in the words quoted. It never substitutes the default for a refused value. A fixed list keeps every label a well-formed ordinal, and the replicate count has its own rule, from 1 to 100000.'),
  ('appliedai', 'advanced', 'module', 'm05-boundaries-ties-and-caps', 8, 'At level 0.9, system A''s mean nDCG on seed 7 with 2000 replicates gives the bounds 0.671684 and 0.838560. How does the engine label them?', '["Letter-P outcome labels, which the platform uses for any fifth and ninety-fifth percentile", "\"lower 90 percent bound\" and \"upper 90 percent bound\" of the interval", "\"5th percentile of the bootstrap mean\" and \"95th percentile of the bootstrap mean\"", "\"10th percentile of the bootstrap mean\" and \"90th percentile of the bootstrap mean\""]'::jsonb, 2, 'Each bound is a percentile of a statistic, so it is labelled as a parameter percentile, and at level 0.9 the tails are the 5th and 95th percentiles, in the words quoted. P labels are kept for outcomes and never used here. The engine''s labels name the percentile itself, and the 10th and 90th labels belong to level 0.8, whose bounds are 0.691350 and 0.822582.'),
  ('appliedai', 'advanced', 'module', 'm05-boundaries-ties-and-caps', 9, 'Why does the engine round each bootstrap tail to 12 decimals before reading the quantile?', '["In floating point (1 - 0.95) / 2 lands a few bits above 0.025, which would move the quantile index off a whole number", "So that the interval prints at six decimals like every other figure the course quotes, with no trailing digits left over", "To make the tails agree with linear interpolation, the alternative quantile the platform chose to follow", "Because the seed is a 12-digit number, and the tails are drawn from the stream at that same precision"]'::jsonb, 0, 'At 2000 replicates the lower tail 0.025 gives an index of 50, a whole number, and the whole-number case takes the mean of the 50th and 51st smallest replicates. A tail a few bits above 0.025 would give an index just above 50 and take the ceil, the 51st, a different value. Rounding the tail to 12 decimals restores 0.025. Printing is separate, the platform''s quantile is not linear interpolation, and the seed is not drawn at any precision.'),
  ('appliedai', 'advanced', 'module', 'm05-boundaries-ties-and-caps', 10, 'Which seeds does the bootstrap accept at its boundaries, and which does it refuse?', '["1 and 4294967295 are accepted; 0 and 4294967296 are refused", "0 and 4294967296 are accepted; only -1 is refused", "Any whole number is accepted, and a missing seed defaults to 7", "0 and 4294967295 are accepted; -1 and 4294967296 are refused"]'::jsonb, 3, 'The boundary table probes the seed either side: 0 and 4294967295 run, -1 and 4294967296 are refused with "seed must be a whole number from 0 to 4294967295". The seed has no default: leaving it out is refused with the same message. Seed 7 is the course''s teaching seed, stated with every bootstrap figure.'),
  ('appliedai', 'advanced', 'module', 'm05-boundaries-ties-and-caps', 11, 'A ranking call passes 5000 documents, and a second passes 5001. What happens to each?', '["Both run, since the cap only warns, and the 5001st document is ranked after all the others as usual", "5000 run, since the cap is inclusive; 5001 is refused with \"documents has 5001 entries, above the 5000 this engine accepts\"", "5000 is refused as well, since the cap is exclusive and the engine accepts only fewer than 5000 documents", "Both are refused, since MAX_DOCS limits the passages a query can rank to 1000, the largest cutoff k"]'::jsonb, 1, 'Each cap is probed at the limit, where the call is accepted, and one above, where it is refused with the field and the cap named. MAX_DOCS is 5000 and applies to the documents one call accepts; MAX_K, 1000, is the largest cutoff, a separate rule. A cap never warns: it lets the call run exactly or refuses it.'),
  ('appliedai', 'advanced', 'module', 'm05-boundaries-ties-and-caps', 12, 'k 0, k 2.5 and k 1001 are each passed to rankBm25. What does the engine return for each?', '["k 0 and k 2.5 are refused, and k 1001 is capped at 1000 with a note saying that the cutoff was reduced", "k 2.5 is rounded to 3 and run; k 0 and k 1001 are each refused with two different messages of their own", "The same refusal every time, \"k must be a whole number from 1 to 1000\", since all three break one rule", "An empty list with a note for k 0, while k 2.5 and k 1001 are refused as lying outside the engine''s stated range"]'::jsonb, 2, 'The cap on k shares its message with the range rule: k must be a whole number from 1 to 1000, and 0, 2.5 and 1001 all break it, so each is refused in the same words with the field `k` named. The engine never caps, rounds or empties a list in place of refusing. Most other caps have their own sentence, naming the count that was passed.'),
  ('appliedai', 'advanced', 'module', 'm05-boundaries-ties-and-caps', 13, 'A calibration call passes 100001 rows. What comes back, and which other input shares the cap?', '["The first 100000 rows are scored and the last is dropped; bootstrap values share the same cap", "\"bins must be a whole number from 1 to 100\", as the rows overflow the bins; no other input shares it", "A result with a note that the Brier score was sampled; the bootstrap replicates share MAX_ROWS", "\"yTrue has 100001 rows, above the 100000 this engine accepts\"; kappa rating pairs share MAX_ROWS"]'::jsonb, 3, 'MAX_ROWS is 100000 and covers the calibration rows and the kappa rating pairs; one above is refused in the words quoted, naming `yTrue`. Nothing is truncated or sampled. The bins message belongs to the bin count, and the bootstrap has its own caps: MAX_VALUES 10000 for values and MAX_BOOT 100000 for replicates.'),
  ('appliedai', 'advanced', 'module', 'm05-boundaries-ties-and-caps', 14, 'How does the claim reader treat "-2" after a space and "Ekene-2" in an answer?', '["\"-2\" after a space is a negative number; in \"Ekene-2\" the minus follows a letter, so it is an identifier", "Both are the number -2, since a minus sign always makes the digits written after it a negative number", "Both are identifiers, since a minus sign is always split off by the tokeniser before any of the claims are read", "\"-2\" is a date fragment and \"Ekene-2\" the number 2, since the hyphen separates the well name"]'::jsonb, 0, 'The boundary table states the rule: a leading minus counts only after a non-alphanumeric character, so "-2" after a space is a negative number, and after a letter or digit, as in "Ekene-2", the text is part of an identifier and makes no claim. Well names would otherwise produce negative numbers. The tokeniser is not the claim reader, and neither text is a date.'),
  ('appliedai', 'advanced', 'module', 'm05-boundaries-ties-and-caps', 15, 'A bootstrap call passes 1 replicate, and another passes 1 value. How does the engine treat the two calls?', '["Both run, each returning a standard error of 0.000000 and a note that one draw gives no spread at all", "Both are refused, since the bootstrap needs at least 2 of each, with messages naming nBoot and values", "The replicate call runs, with the standard error null and the note \"one replicate: the standard error is undefined\"; the value call is refused", "The value call runs with its interval equal to the one value; the replicate call is refused by name"]'::jsonb, 2, 'One replicate is accepted, since nBoot runs from 1 to 100000, and the standard error, the SD of the replicates with divisor nBoot - 1, has no value, so it is returned as null with the note quoted: a result with a note. One value is refused, "values has 1 value: the bootstrap resamples at least 2". Nothing is set to 0 in place of an undefined figure.'),
  ('appliedai', 'advanced', 'module', 'm06-reading-the-engine-honestly', 1, 'What does the evaluation engine import, and what does it call beyond them?', '["lib/stats and a hosted language model, which it calls once for every answer in order to judge each claim", "Nothing at all: every function, log loss included, is written out again inside the engine", "lib/stats, lib/conventions/percentile.js and engines/dataai/ml.js, and it makes no network call", "scikit-learn through a bridge, which it calls for TF-IDF, kappa and the calibration curve"]'::jsonb, 2, 'The course checks the engine''s imports and source: lib/stats (mulberry32 and quantile), lib/conventions/percentile.js and, from the machine learning engine, logLoss, with no network call. It runs no language model. Log loss is imported and never re-implemented. scikit-learn is a witness the engine''s figures are compared with, never a dependency.'),
  ('appliedai', 'advanced', 'module', 'm06-reading-the-engine-honestly', 2, 'A tool built around the engine uses a language model to draft answers. How does the course treat that output?', '["As an input, scored by the same deterministic checks as the fixture answers, and never as a key, label or judgment", "As a second annotator, whose grades are compared with the primary ones by kappa and then averaged into the key", "As the key for any query with no reference answer, since a model can answer where the judged set cannot", "As a check on the engine: a claim the model accepts is marked supported even when no cited passage holds it"]'::jsonb, 0, 'A model''s output changes from run to run and between model versions, so a key resting on it would have no fixed right answer. The course''s rule is that it is an input to be scored, by claims against cited and retrieved passages, exact match and token F1, and extraction outcomes. It never becomes a key, a label or a judgment, and it overrides no check.'),
  ('appliedai', 'advanced', 'module', 'm06-reading-the-engine-honestly', 3, 'Why does a capstone field in this course have exactly one right answer?', '["It is the median of several model runs on the same prompt, which removes the variation between one run and the next", "It is a return value of the engine on inputs written down in advance, so the same inputs give the same number on any machine", "Its tolerance is wide enough that any reasonable method lands inside it, whatever the settings the learner chooses", "It is typed by hand into the grader from the lesson text, so the grader and the learner read the same figures"]'::jsonb, 1, 'Every graded number is computed by a named engine function on fixed inputs, and the only random draw is the seeded bootstrap, named exactly by its seed and replicate count. No model output enters. Tolerances are made in one place and never typed, and they exist to absorb rounding, never method choice.'),
  ('appliedai', 'advanced', 'module', 'm06-reading-the-engine-honestly', 4, 'System B''s Q05 answer dates Ekene-6''s water breakthrough 2024-09-01, and the date is in EKD-027, which it cites and retrieved. What do the checks return, and what does that show?', '["The claim is unsupported, since EKD-027 is about another well and the check reads which well a passage covers", "The claim is supported and exact match 1, since a supported date is scored as a correct short answer", "The claim is flagged notRetrieved, since EKD-027 was not in system B''s top 5 for the query Q05", "The claim is supported and the short answer scores exact match 0: grounded says nothing about truth"]'::jsonb, 3, 'The check finds the date in a cited, retrieved passage, so the claim is supported; EKD-027 is about Ekene-3''s breakthrough, and Ekene-6 broke through on the reference date 2024-03-01, so the short answer scores exact match 0. The check cannot know a passage is about another well. EKD-027 was retrieved and cited, so no flag is raised.'),
  ('appliedai', 'advanced', 'module', 'm06-reading-the-engine-honestly', 5, 'The engine keeps the (k1 + 1) factor in the BM25 numerator, where Lucene 8 and later drop it. What does that choice change?', '["The size of every score by one common factor, leaving the order of the passages identical", "The order of the passages, since dropping the factor favours those passages with repeated terms", "Nothing at all: the two forms give the same scores to every printed decimal on the Ekene corpus", "The idf of each term, since Lucene 8 moves the factor inside the logarithm of the idf"]'::jsonb, 0, 'The course names this choice as Robertson and Zaragoza''s form: dropping (k1 + 1) scales every score and leaves the order. So a BM25 score from this engine and one from Lucene 8 differ in size for the same passage while the rankings agree. The idf is unaffected, and the scores do differ, so the choice is named whenever a score is compared across tools.'),
  ('appliedai', 'advanced', 'module', 'm06-reading-the-engine-honestly', 6, 'Which common alternative to the engine''s BM25 idf does the course name, and why did the engine decline it?', '["The smoothed TF-IDF idf, which adds 1 to both counts; BM25 needs no smoothing on small corpora", "The Robertson form, which ignores document frequency; the Lucene form was chosen for its speed", "The Robertson form, which goes negative for common terms; the Lucene form is never negative", "Raw document frequency, which rewards common terms; the Lucene form divides by the corpus length"]'::jsonb, 2, 'The engine uses the Lucene idf ln(1 + (N - df + 0.5) / (df + 0.5)), which adds 1 inside the logarithm, so even a term in every passage keeps a small positive idf; the Robertson form without that 1 goes negative for common terms. The smoothed idf belongs to TF-IDF. The Robertson form does use document frequency, and speed is not the stated reason.'),
  ('appliedai', 'advanced', 'module', 'm06-reading-the-engine-honestly', 7, 'The engine divides average precision by every relevant judged passage. Which alternative does it decline, and what does its choice do to a missed passage?', '["Dividing by k; under the engine''s rule a missed passage is left out of AP entirely and changes nothing", "Dividing by the relevant passages retrieved; under the engine''s rule a missed one raises AP", "Dividing by the judged passages; under the engine''s rule a missed one counts only at grade 3", "Dividing by min(k, relevant); under the engine''s rule a relevant passage never retrieved lowers AP"]'::jsonb, 3, 'The course''s table names min(k, relevant) as the common alternative and trec_eval as the reason for the engine''s choice: every relevant judged passage is in the divisor, so one never retrieved lowers the average. On the stated ranking c, a, x, b, d this gives 0.400000, where dividing by the 3 relevant passages retrieved would give 0.533333, which the engine does not compute. Dividing by k is precision''s rule.'),
  ('appliedai', 'advanced', 'module', 'm06-reading-the-engine-honestly', 8, 'The groundedness check accepts only cited and retrieved passages, with numericRelTol 0 by default. Which question does that make it answer?', '["Is this figure somewhere in our documents, whether cited or not?", "Could a reader trace this figure to what the system saw and cited?", "Is this figure true of the field on the very date the answer names?", "Did a language model agree that the figure was a well sourced one?"]'::jsonb, 1, 'The course states the engine''s reason: a claim must be traceable to what the system saw. Accepting any passage of the corpus is the alternative, and it answers whether the figure exists somewhere, a weaker question. No check in the engine decides whether a figure is true, and no model is asked anything.'),
  ('appliedai', 'advanced', 'module', 'm06-reading-the-engine-honestly', 9, 'An evaluation report states system A''s MAP at 5 as 0.600278 and system B''s as 0.593007, and concludes that A retrieves better. What has it left out that the course''s table shows can reverse the verdict?', '["The seed: on seed 8 the two MAP figures change places, so the seed must be stated", "The gain: under exponential gain B''s MAP at 5 rises above A''s, so the gain decides", "The bin count: MAP is read from bins, and at 15 bins the order of A and B reverses", "The relevance threshold: at grade 2 or more B leads, 0.771014 against A''s 0.750362"]'::jsonb, 3, 'At grade 1 system A''s MAP is the higher, 0.600278 against 0.593007; at grade 2 system B''s is, 0.771014 against 0.750362. The threshold is a choice that changes figures and order together, so it is stated with every figure. MAP draws no seed, uses no gain and no bins: the gain belongs to nDCG and the bins to calibration.'),
  ('appliedai', 'advanced', 'module', 'm06-reading-the-engine-honestly', 10, 'Which of these does the course list among what is not built?', '["The paired bootstrap, the tie key, the stop list and the reliability table at a stated bin count", "A p-value, a reranker, stemming, and any fitting of the classifier behind the calibration set", "Cohen''s kappa with linear weights, the SQuAD normalisation and the Murphy decomposition", "Log loss, which the engine computes with its own formula beside the Brier score"]'::jsonb, 1, 'The course''s list of what is not built includes no language model, no embedding or dense retrieval, no reranker, no stemming or synonyms, no query expansion, no model judging an answer, no truth check beyond finding a claim in a cited passage, no p-value, and no fitting of the calibration classifier. The paired bootstrap, the tie key, the stop list, weighted kappa, SQuAD matching and the Murphy decomposition are all built. Log loss is built by import from the machine learning engine.'),
  ('appliedai', 'advanced', 'module', 'm06-reading-the-engine-honestly', 11, 'An evaluation report quotes a paired bootstrap interval for the nDCG difference. What must travel with it?', '["The seed, the replicate count, the level, and whether the bootstrap was paired", "The p-value, which the engine prints beside the share at or below 0 for each comparison", "The bin count and the edge rule, which decide where the replicates fall in the interval", "The model version that drew the replicates, so the interval can be regenerated later"]'::jsonb, 0, 'A bootstrap figure is named exactly by its seed, replicate count and level, and the course''s report checklist adds whether it was paired, since the unpaired interval is wider. On seed 7, 2000 replicates and level 0.95 the paired interval runs from -0.068015 to 0.058726; on seed 8 it is -0.063543 to 0.055562. The engine prints no p-value, bins belong to calibration, and no model draws anything.'),
  ('appliedai', 'advanced', 'module', 'm06-reading-the-engine-honestly', 12, 'The course''s worked report paragraph ends "On this judged set the two systems cannot be told apart". Which findings support that sentence?', '["System B''s MRR is higher, 0.923913 against 0.880435, which outweighs A''s higher MAP on the same queries", "Both systems retrieved no unjudged passage at k 5, which makes their scores equal by the pooling rule", "The paired nDCG interval runs across 0, and the second annotator''s grades reverse the order of the systems", "The Brier score of 0.168382 shows the judged grades are poorly calibrated, so no comparison can hold"]'::jsonb, 2, 'The paired bootstrap of A minus B, seed 7, 2000 replicates, level 0.95, gives an interval from -0.068015 to 0.058726, across 0; and on the second annotator''s grades A leads on mean nDCG where B led on the primary grades. Two independent checks agree. MRR against MAP is a split verdict, zero unjudged passages says the key covers both systems, and the Brier score measures a classifier''s probabilities.'),
  ('appliedai', 'advanced', 'module', 'm06-reading-the-engine-honestly', 13, 'The tokeniser keeps single-character tokens, where scikit-learn''s default word pattern needs two characters or more. Why?', '["Single characters are stop words, so the engine keeps them only for as long as the stop list is off", "A learner can tokenise by hand, and single characters such as the 3 of Ekene-3 carry meaning", "To match scikit-learn''s default exactly, so that its TF-IDF figures compare to every decimal", "Single characters are removed later by stemming, so keeping them at this early stage costs nothing at all"]'::jsonb, 1, 'The course''s table gives the reason: a learner can tokenise by hand, and single-character tokens such as well numbers matter. "Ekene-3" becomes ekene and 3, and a two-character pattern would drop the 3. This is a departure from scikit-learn''s default word pattern, and the engine does no stemming at all. The stop list is a separate switch, off by default.'),
  ('appliedai', 'advanced', 'module', 'm06-reading-the-engine-honestly', 14, 'How does the course use the word "AI"?', '["For any automated step, so the BM25 ranking and the claim check are both called AI here", "To name the engine itself, which the app and the course describe as an AI system", "For the bootstrap only, as the one part of the engine that draws random numbers to score", "To name the system being evaluated; every method the engine runs is named by what it is"]'::jsonb, 3, 'The legislated vocabulary says AI names the system being evaluated, and every method is named by what it is: TF-IDF, BM25, SQuAD matching, a claim check, kappa, a Brier decomposition, a seeded bootstrap. The engine runs no model, so it is never called AI. The bootstrap is a seeded resampling method and is named as such.'),
  ('appliedai', 'advanced', 'module', 'm06-reading-the-engine-honestly', 15, 'An evaluation report gives ECE 0.209300 and MCE 0.723333 for a classifier''s probabilities. What else must it name for those figures to be reproduced?', '["The bin count, 10, and the edge rule, an interior edge opening the upper bin", "The seed and replicate count, since ECE and MCE are bootstrap percentiles", "The cutoff k, since ECE and MCE are read from each query''s top k passages", "Only the Brier score, 0.168382, from which both figures can be rebuilt exactly"]'::jsonb, 0, 'ECE and MCE are computed on bins, so a reader needs the bin count and the edge rule; MCE is 0.660556 at 5 bins and 0.750000 at 15, and the library''s edge rule moves the table. They draw no random numbers. No cutoff enters a calibration figure. The Brier score uses no bins and cannot rebuild a table.'),
  ('appliedai', 'advanced', 'final', null, 1, 'In the Ekene confusion table, rows the primary grades and columns the second annotator''s, the largest off-diagonal cell is row 0, column 1, with 24 pairs. Why does that cell matter most to the retrieval metrics'' default setting?', '["It holds the pairs where both annotators agree on grade 1, so it is the base every relevant passage in the metrics rests on", "It holds the three-grade reversals, which quadratic kappa charges 9 each and which drive the weighted kappa down", "It is where the second annotator''s draw moved two grades, the rarer move, so it measures the fixture''s own noise", "It holds passages one annotator calls not relevant and the other related, which is the grade 1 line the default threshold draws"]'::jsonb, 3, 'Row 0, column 1 counts pairs the primary annotator graded 0 and the second graded 1. At the default relevantGrade of 1, those passages flip between not relevant and relevant depending on the key. The diagonal holds agreement; a three-grade reversal would sit in a far corner; and a one-grade move is the common draw, with probability 0.25.'),
  ('appliedai', 'advanced', 'final', null, 2, 'What are the observed agreement and the kappa when each Ekene grade is first reduced to relevant or not at grade 2 or more?', '["Observed agreement 0.928962 and kappa 0.794115", "Observed agreement 0.814208 and kappa 0.634430", "Observed agreement 0.721311 and kappa 0.771549", "Observed agreement 0.928962 and kappa 0.579841"]'::jsonb, 0, 'At grade 2 or more the derived two-way ratings agree on 0.928962 of the pairs with kappa 0.794115. 0.814208 and 0.634430 belong to the grade 1 reduction. 0.721311 is the four-grade observed agreement and 0.771549 the quadratic kappa on four grades. 0.579841 is the four-grade unweighted kappa.'),
  ('appliedai', 'advanced', 'final', null, 3, 'From the quadratic row of the Ekene agreement table, observed disagreement 0.459016 and expected disagreement 2.009257, which figure does the engine''s formula give?', '["A kappa of 0.459016, since the observed disagreement is the figure kappa reports", "A kappa of 0.721311, the observed agreement, which weights never alter at all", "A kappa of 0.771549, one minus the ratio of the two", "No kappa: a disagreement above 1 makes the quadratic weighting undefined here"]'::jsonb, 2, 'Kappa is 1 - sum w O / sum w E, the same formula for every weighting, so 1 - 0.459016 / 2.009257 gives 0.771549. A disagreement is an input to kappa, never kappa itself. The observed agreement 0.721311 is reported unweighted in every row and is not a kappa. A weighted disagreement above 1 is expected, because a weight can exceed 1.'),
  ('appliedai', 'advanced', 'final', null, 4, 'Four calls are made. Which one is a refusal, as distinct from a result returned with a note?', '["cohenKappa where both raters give every item the same label, 2, which names no field", "retrievalMetrics for system A on Q24, where recall and average precision have no value", "checkGroundedness on an answer that states no quote, date or number for the check", "cohenKappa with rater a an empty list, which names the field `a`"]'::jsonb, 3, 'An empty rater list is refused: "a must be a non-empty array of ratings", with the field named. The other three calls run on valid inputs and return a figure as null with the reason beside it: kappa when the expected disagreement is 0, recall and average precision on Q24 where no judged passage has grade 1 or more, and the supported fraction of an answer with no checkable claim.'),
  ('appliedai', 'advanced', 'final', null, 5, 'A kappa call passes 51 distinct labels. What does the engine return?', '["A kappa over the first 50 labels, with a note that the last label was dropped from the table", "A refusal: \"labels[2] repeats 1\", as 51 labels on a four-grade scale must hold a repeat", "A refusal: \"labels has 51 entries, above the 50 this engine accepts\"", "A kappa, since MAX_LABELS limits only the calibration bins and has no effect on the kappa"]'::jsonb, 2, 'MAX_LABELS is 50, and one above is refused with the field and the cap named, in the words quoted. No label is dropped quietly. The repeat message is for a label listed twice, and 51 distinct labels hold no repeat. MAX_LABELS is the kappa cap; the calibration bins have their own cap, MAX_BINS 100.'),
  ('appliedai', 'advanced', 'final', null, 6, 'A team reads the Ekene annotators'' unweighted kappa, 0.579841, as evidence that system B retrieves better than system A. What is wrong with that reading?', '["Kappa measures how far two raters agree on the grades; it says nothing about either system", "Kappa of 0.579841 favours system A, since it is closer to A''s MAP than to B''s on the same key", "The reading is sound, since a kappa above 0.5 means the higher-scoring system is the better one", "Kappa compares the two systems'' rankings query by query, so it favours neither when it is positive"]'::jsonb, 0, 'Kappa is computed from two raters'' labels on the same items, the primary and second annotators'' grades here, and no system output enters it. It tells a reader how stable the key is, and a modest kappa warns that a small difference between systems may be the annotators disagreeing. No kappa threshold names a better system, and kappa never compares rankings.'),
  ('appliedai', 'advanced', 'final', null, 7, 'A second classifier is scored on the same 200 Ekene rows and returns a different Brier score. Which decomposition term must be identical for the two classifiers?', '["Reliability, 0.080032, since it is set by the bin edges alone", "Resolution, 0.064570, since both use the same 10 bin edges", "WBC, 0.001669, since the six stated rows fix the covariance", "Uncertainty, 0.153900, since it depends on the outcomes alone"]'::jsonb, 3, 'UNC is base rate x (1 - base rate) and the base rate belongs to the outcomes, so any classifier on these rows has UNC 0.153900. Reliability depends on each bin''s mean probability, resolution on each bin''s observed frequency, and both follow where the probabilities put the rows. WBC depends on the probabilities inside each bin; the six stated rows are a separate worked example.'),
  ('appliedai', 'advanced', 'final', null, 8, 'The Ekene ECE of 0.209300 equals the mean probability over all 200 rows minus the base rate. What is that mean probability?', '["0.190000", "0.399300", "0.168382", "0.209300"]'::jsonb, 1, 'Because every non-empty bin is over-confident, ECE comes to the mean probability minus the base rate, 0.399300 - 0.190000 = 0.209300. 0.190000 is the base rate itself, 0.168382 the Brier score, and 0.209300 the ECE, which the subtraction produces.'),
  ('appliedai', 'advanced', 'final', null, 9, 'In the ten-bin Ekene table, which bin''s observed frequency sits farthest from the base rate of 0.190000, and so adds most to resolution per row?', '["Bin 7, where 3 rows carry the largest gap, 0.723333", "Bin 2, the bin holding the most rows, 39 of the 200", "Bin 9, where 0.904762 of the 21 rows are relevant", "Bin 6, with 15 rows and an observed frequency of 0"]'::jsonb, 2, 'Resolution is sum n_k (observed_k - base rate)^2 / N, and bin 9''s 0.904762 is the farthest observed frequency from 0.190000 in either direction. Bin 7''s figure is its gap between mean probability and frequency, which feeds reliability and MCE. Bin 2 has the most rows and an observed frequency of 0.128205, near the base rate. Bin 6''s frequency, 0, lies 0.190000 away, far less than bin 9''s distance.'),
  ('appliedai', 'advanced', 'final', null, 10, 'Which two figures in a calibration result need neither a bin count nor an edge rule to be reproduced?', '["ECE and MCE, since each is read off the whole reliability table at once", "REL and RES, since the bins cancel inside the decomposition", "The Brier score and log loss, since each is a mean over rows", "The closure and WBV, since both are 0 up to rounding anyway"]'::jsonb, 2, 'The Brier score is mean (p - y)^2 and log loss a mean of logarithms over rows, so neither uses a bin. ECE and MCE are computed from the bins and move with them, as MCE does from 0.660556 at 5 bins to 0.750000 at 15. REL and RES are bin sums, and REL moves under the library''s edge rule. WBV is a within-bin spread, 0.000689 at 10 bins, well above rounding.'),
  ('appliedai', 'advanced', 'final', null, 11, 'A report computes the pooled within-bin covariance of the Ekene rows at 10 bins and prints it in the WBC line of its decomposition. What is wrong?', '["WBC as Stephenson, Coelho and Jolliffe (2008) label it is twice that covariance; the engine''s WBC, 0.001669, is the paper''s", "Nothing: WBC is the pooled within-bin covariance, and the engine''s 0.001669 is that covariance printed at six decimals", "The covariance should be halved before it is printed, since the paper''s eq. 7 splits it across the WBV and WBC lines", "WBC is the within-bin variance of the probabilities, 0.000689 on these rows, so the covariance belongs on another line"]'::jsonb, 0, 'The paper writes the fifth term of eq. 7 as -(2/N) sum (y - observed_k)(p - mean p_k) and names it -WBC, so WBC carries the factor 2. The engine''s WBC is the paper''s, and printing the bare covariance as WBC is a real wrong method that leaves the identity open. Nothing is halved or split, and 0.000689 is WBV.'),
  ('appliedai', 'advanced', 'final', null, 12, 'A reviewer writes the Ekene decomposition as REL - RES + UNC + WBV - 2 WBC and substitutes the engine''s five figures. What does the sum do?', '["It lands on 0.168382, since the engine prints only half of WBC and the reviewer''s 2 restores the missing half", "It misses the Brier score of 0.168382, since the 2 is counted twice when the engine''s WBC already carries it", "It lands on 0.169362, the three classic terms, because the two within-bin terms cancel under that form", "It closes at -8.33e-17 as before, since a factor on a term as small as WBC is lost in the rounding"]'::jsonb, 1, 'The engine''s identity is Brier = REL - RES + UNC + WBV - WBC with no further 2, because WBC as the paper labels it already includes the factor. Subtracting 2 WBC removes an extra 0.001669 and the sum no longer equals 0.168382. The engine prints WBC whole. 0.169362 is REL - RES + UNC alone, and 0.001669 is far larger than any rounding.'),
  ('appliedai', 'advanced', 'final', null, 13, 'The Ekene rows are decomposed at 5, 10 and 15 bins. Which figures can move with the bin count, and which cannot?', '["REL and RES can move; UNC and the Brier score cannot", "UNC and the Brier score move; REL and RES stay fixed", "All five terms move, and the Brier score moves with them", "None move: the decomposition is fixed by the 200 rows"]'::jsonb, 0, 'REL and RES are sums over bins, so the bins decide them, as the one-bin case shows with RES 0.000000. UNC depends on the outcomes alone and the Brier score is a mean over rows, so both hold at 0.153900 and 0.168382. The within-bin terms move with the bins too, but the Brier score they close to does not.'),
  ('appliedai', 'advanced', 'final', null, 14, 'Comparing the engine''s bin-edge rule with scikit-learn''s on the Ekene rows at 10 bins, which of REL, ECE and MCE differ?', '["All three, since 6 of the 10 bins hold a different number of rows", "ECE alone, since it weights each bin by the rows the rule moves in", "None, since the rule moves only 17 rows out of the full 200 rows", "REL alone, by -1.18e-3; ECE and MCE come out the same on this set"]'::jsonb, 3, 'By the library rule REL is 0.078849 against the engine''s 0.080032; ECE 0.209300 and MCE 0.723333 agree, ECE because every bin is over-confident and MCE because bin 7 holds no edge value. Six bins change their counts, yet only REL moves on this set. Seventeen rows are enough to move REL, so the rule is named whenever tables are compared.'),
  ('appliedai', 'advanced', 'final', null, 15, 'The log loss of the Ekene rows reports 5 probabilities clipped. What does that count say about the calibration set?', '["It holds probabilities of exactly 0 or 1, whose cost is set by eps 1e-15", "Five rows were dropped from the log loss mean as out of range, so it runs over fewer rows", "Rows on an interior bin edge, five of them, which log loss moves into the lower bin", "Five probabilities were above 0.5 on rows whose outcome was 0, the confident misses"]'::jsonb, 0, 'Clipping moves a probability into [eps, 1 - eps] only when it lies outside that range, which for probabilities given to 2 decimals means exactly 0 or 1; each clipped row''s cost is then set by eps. No row is dropped, log loss uses no bins, and a confident miss such as 0.9 on an outcome of 0 is not clipped.'),
  ('appliedai', 'advanced', 'final', null, 16, 'Scored under the primary grades and again under the second annotator''s, at k 5 and grade 1, which metric keeps the same order of systems A and B on both keys?', '["Mean nDCG: B leads on both, 0.764137 against 0.762753 and 0.701037 against 0.718064", "Neither: both MAP and mean nDCG change leader when the key changes to the second one", "MAP: A leads on both, 0.600278 against 0.593007 and 0.551119 against 0.542743", "MRR, the only metric the course reports under the second annotator''s grades at all"]'::jsonb, 2, 'Under the primary grades A''s MAP 0.600278 beats B''s 0.593007, and under the second annotator A''s 0.551119 beats 0.542743, so MAP keeps its order. Mean nDCG flips: B leads on the primary grades and A, 0.718064 against 0.701037, on the second. The course''s second-annotator table reports MAP and mean nDCG and leaves MRR out.'),
  ('appliedai', 'advanced', 'final', null, 17, 'Judging the 80 unjudged passages that BM25 at k 10 retrieves could move its MAP of 0.670893 which way?', '["Either way: a passage judged relevant adds precision at its rank and also enlarges its query''s divisor", "Only upward, since every unjudged passage now scored 0 can only gain grade when an assessor finally reads it", "Only downward, since the newly judged passages raise the number of relevant passages the run is measured on", "Not at all, since MAP reads only the relevant passages the run retrieved and those are judged already"]'::jsonb, 0, 'Every one of the 80 sits in the run''s own lists. Judged relevant, a passage adds a precision term at its rank and also joins the divisor of every relevant judged passage for its query, so that query''s average precision rises when the passage sits high in the list and can fall when it sits near the foot. Judged not relevant, it leaves the figure as it stands. So judging can move MAP either way, which is why the course says those figures bound nothing in either direction until the passages are judged.'),
  ('appliedai', 'advanced', 'final', null, 18, 'Under the primary grades, system A''s evaluateRetrieval at k 5 lists Q24 as excluded. What reason does the engine give?', '["\"runs has no ranking for query Q24\"", "\"the query has no token, so no document is ranked\"", "\"nDCG is undefined: the query has no judged documents, so the ideal DCG is 0\"", "\"no judged document has grade 1 or more\""]'::jsonb, 3, 'The no-relevant rule excludes a query with no judged passage at grade 1 or more and lists it with the reason quoted. Q24 has a ranking and 8 judged passages, all at grade 0, so neither the missing-ranking refusal nor the no-judged-documents note applies, and its query text holds tokens.'),
  ('appliedai', 'advanced', 'final', null, 19, 'With noRelevant set to ''zero'' in place of the default, how do system A''s MAP and the query count change?', '["Q24 is dropped from the list of excluded queries, and A''s MAP rises to 0.670893 over 24 queries", "Q24 is kept and scored 0, so 24 queries enter the means and A''s MAP falls from 0.600278 to 0.575266", "Nothing changes, since Q24 has no relevant passage and adding a zero changes nothing in a mean over 23 queries", "The call is refused: \"noRelevant must be ''exclude'' or ''zero''\", since zero is not a rule it offers"]'::jsonb, 1, 'Under ''zero'' the query nothing answers is kept with every metric it cannot give scored 0, so the mean is over 24 queries and falls to 0.575266, and Q24 is listed as zeroed. A zero added to the count does change a mean. 0.670893 is BM25''s MAP at k 10. ''zero'' is one of the two rules offered.'),
  ('appliedai', 'advanced', 'final', null, 20, 'A new team wants the test set for its copilot kept safe. Which practice does the course prescribe?', '["Score the copilot twice and discard any run that reaches 24 exact matches of 24 as a likely leak of the key", "Run the groundedness check, which flags any answer whose figure was copied from the reference", "Keep the judged queries and their references out of every prompt, every example and every fine-tuning set", "Raise the relevance threshold to grade 2 or more, so that a leaked key earns rather less credit in the means"]'::jsonb, 2, 'No score can tell a leaked key from skill, because a leaked answer compares perfectly with its reference, so the leak is prevented by process before the score is computed. Discarding a perfect run would punish a system that is simply right. Groundedness checks cited passages and cannot see where a figure came from. The threshold changes retrieval metrics and leaves short-answer matching alone.'),
  ('appliedai', 'advanced', 'final', null, 21, 'A pooled key is set beside a full key that keeps every grade the pool gave and adds an assessor''s grades for the passages a new system retrieved that the pool left unjudged. Where in their confusion table do all the disagreements fall?', '["Along the diagonal, since the pooled key and the full judging agree on every passage that the pool happened to judge", "In the column where the assessor says 0 and the pooled key gives grade 1 or more, since pools over-grade passages", "Spread evenly over the table, since pooling errors are random and fall on both sides of the diagonal equally", "In the row where the pooled key says 0 and the assessor gives grade 1 or more, since the key scores every unjudged passage 0"]'::jsonb, 3, 'On the passages the pool judged, both keys carry the same grade, because the full key keeps them; the rest are unjudged, which the pooled key scores 0, so every disagreement sits where the key says 0 and the assessor says 1 or more. A one-sided table is the signature of pooling bias. The diagonal is agreement, pools never grade an unjudged passage above 0, and the error is systematic.'),
  ('appliedai', 'advanced', 'final', null, 22, 'BM25 at k 5 reports a tie at the cutoff on four queries. Which, and what does a metric computed there depend on?', '["Q06, Q10, Q14 and Q24; the length of the tied passages decides which of them stay inside the cut", "Q01, Q06, Q17 and Q22; the scores alone decide, since tied passages are reported past the cutoff", "Q01, Q06, Q17 and Q22; the id order of the tied passages decides which stay inside the cut", "Q10 alone, the duplicate spill note; ties elsewhere are broken by score at the full double first"]'::jsonb, 2, 'Across the 24 queries at k 5, BM25 flags tieAtCutoff on Q01, Q06, Q17 and Q22, and TF-IDF on Q22. When the cut falls inside a tie, the id ascending decides which tied passages stay, so the metric depends on the ids. The list is never lengthened past k. Q10 ties at rank 1 and 2 with a list of 2, which falls inside the cut only at k 1.'),
  ('appliedai', 'advanced', 'final', null, 23, 'At relevantGrade 2, a passage graded 2 sits exactly on the threshold and one graded 1 sits just below. How does the engine treat the two?', '["Neither is relevant, since a passage counts only strictly above the threshold, as a limit is always exclusive", "The grade 2 passage is relevant, since the threshold names the lowest relevant grade; the grade 1 passage is not", "Both are relevant, since any passage with a grade of 1 or more counts, whatever value the relevantGrade happens to be set to", "The grade 2 passage is relevant only for nDCG, while precision and recall ignore any grade under 3 altogether"]'::jsonb, 1, 'The boundary table states that a grade equal to relevantGrade is relevant and a grade one below is not. Boundaries are per rule: this one includes its limit. relevantGrade replaces the default of 1 when it is passed. nDCG uses every grade as gain and ignores the threshold, while precision and recall follow it.'),
  ('appliedai', 'advanced', 'final', null, 24, 'Q10 by BM25 ranks only 2 passages, both relevant. What precision at 5 does the engine return, and why?', '["0.400000, since precision at k divides by k even when fewer than k are ranked", "1.000000, since both of the passages ranked are relevant and precision reads the list", "Null with a reason, since a list shorter than k leaves precision at k undefined", "0.500000, since the engine divides by the relevant passages the query was judged to have"]'::jsonb, 0, 'The basis states precision: relevant in the top 5 / 5, 5 even when fewer are ranked, so 2 / 5 = 0.400000. Dividing by the passages ranked is the common alternative the engine declined, following trec_eval. A short list is a result, never a null, and dividing by the relevant judged passages is recall.'),
  ('appliedai', 'advanced', 'final', null, 25, 'A retrievalMetrics call is made at k 3, where the first relevant passage sits at rank 4. What reciprocal rank does it return?', '["0.250000, one over the rank of the first relevant passage wherever it sits in the list", "0: a relevant passage at rank k + 1 does not count, so there is none in the top k", "Null with a note, since the first relevant passage lies outside the stated cutoff", "0.333333, one over k, as the engine credits a passage found just past the cutoff"]'::jsonb, 1, 'The basis says reciprocal rank is 1 / rank of the first relevant document in the top k, and 0 when there is none; the boundary table confirms a relevant passage at rank k counts and at rank k + 1 does not. So the value is 0. Reciprocal rank never looks past the cutoff and is never null for a query with a relevant passage.'),
  ('appliedai', 'advanced', 'final', null, 26, 'An answer writes "45% water". How does the claim reader take the figure?', '["As the number 45, since a percent sign is ignored when a number claim is read", "As a quote, since a symbol attached to digits turns the whole figure into quoted text", "As no claim at all, since a figure carrying a unit or a sign makes an identifier of it", "As a fraction of one, since the reader divides a percentage by a hundred before matching"]'::jsonb, 0, 'The claim grammar reads digits with optional comma groups and a decimal part, a percent sign ignored, so "45%" is the number 45 and must equal a passage number at numericRelTol 0. A quote needs double quotation marks. The identifier rule is about a number glued to a letter, or to - _ or / after a letter or digit, and nothing is divided before matching.'),
  ('appliedai', 'advanced', 'final', null, 27, 'An answer cites a passage and writes the date "2023-01-01x". What does the claim reader take from it?', '["The date 2023-01-01, since the reader strips a trailing letter before it matches a date", "Nothing at all, since any text that touches a letter is part of an identifier and is skipped entirely", "A quote, since a date that is followed by a letter is taken as quoted text by the reader", "Numbers only: a date must touch no letter or digit, so the trailing x makes it read as numbers"]'::jsonb, 3, 'The boundary table states the date rule: YYYY-MM-DD touching no letter or digit is a date, and "2023-01-01x" is read as numbers: 2023 is a number claim, and each later piece follows a hyphen after a digit, so it is part of an identifier. The reader strips nothing before matching. A quote needs quotation marks. The identifier rule is about a number directly after a letter, or after - _ or / that follows a letter or digit.'),
  ('appliedai', 'advanced', 'final', null, 28, 'To let any rounded figure stand, someone sets numericRelTol to 1 in checkGroundedness. How does the engine respond?', '["It refuses, naming the field: \"numericRelTol must be a number from 0 (inclusive) to 1 (exclusive)\"", "Every number is supported, since a tolerance of 1 accepts any figure within its own size", "The call runs with numericRelTol capped at 0.002, the setting the course uses for rounding", "A refusal naming `citations`, as a tolerance of 1 means the citations are not checked at all"]'::jsonb, 0, 'numericRelTol runs from 0 up to just below 1, and 1 is refused with the field named, in the words quoted. The engine never caps a value in place of refusing it. 0.002 is a setting the course passes to show a rounded figure standing, and the citations refusal is for citations that are not a list.'),
  ('appliedai', 'advanced', 'final', null, 29, 'A retrievalMetrics call passes a judgment of grade 11 for EKD-018. What does the engine return?', '["The call is refused with the judgment''s path named: \"judgments.EKD-018 must be a whole-number grade from 0 to 10\"", "A result with the grade clipped to 10, the highest grade that the engine accepts at all", "Grades above 3 are read as grade 3 on the four-grade Ekene scale, and a result comes back", "A refusal: \"relevantGrade must be a whole number from 1 to 10\", naming relevantGrade"]'::jsonb, 0, 'Grades 0 and 10 are accepted and -1, 2.5 and 11 are refused, with the judgment''s own path named, in the words quoted. The engine clips nothing. MAX_GRADE is 10, so the four-grade scale belongs to the fixture and the engine''s own limit is 10. The relevantGrade message is for a threshold of 0.'),
  ('appliedai', 'advanced', 'final', null, 30, 'System A''s bootstrap of mean nDCG, seed 7 and 2000 replicates, gives 0.691350 to 0.822582 at level 0.8 and 0.623984 to 0.877278 at level 0.99. Why does the wider interval contain the narrower one?', '["Each level draws its own replicates, and the engine draws more of them at 0.99 so the interval widens", "Every bound is read from the same 2000 sorted replicate means, with the tails simply further out", "The 0.99 interval is the 0.8 one stretched by a ratio of normal quantiles about the mean nDCG", "They need not nest at all; on seed 7 they happen to, and on another seed they could cross over"]'::jsonb, 1, 'One seeded stream gives one set of 2000 replicate means; each level reads its two bounds from that sorted set, the 10th and 90th percentiles at 0.8 and the 0.5th and 99.5th at 0.99, so the intervals nest. The replicate count is set by nBoot and not by the level, no normal quantile enters a percentile interval, and nesting follows from reading one sorted set.'),
  ('appliedai', 'advanced', 'final', null, 31, 'At 2000 replicates and a lower tail of 0.025, which replicate means does the platform''s quantile read for the lower bound?', '["The 50th smallest alone, since a whole index always takes the idx-th smallest value directly, with no mean", "The 51st smallest, the ceiling of the index, since the tail is read a few bits above 0.025", "A linear interpolation between the 50th and 51st smallest, weighted by the fractional index", "The mean of the 50th and 51st smallest, since idx = 2000 x 0.025 = 50 is whole and nBoot is even"]'::jsonb, 3, 'The stated rule: idx = nBoot x p; idx not whole takes the ceil(idx)-th smallest; idx whole with nBoot even takes the mean of the idx-th and (idx+1)-th; idx whole with nBoot odd the (idx+1)-th. Here idx is 50 and nBoot even. The engine rounds each tail to 12 decimals, so 0.025 is read exactly. Linear interpolation is the alternative the platform did not take.'),
  ('appliedai', 'advanced', 'final', null, 32, 'A ranking call passes one passage of 20001 characters as documents[0]. What does the refusal say?', '["\"text has 20001 characters, above the 20000 this engine accepts\" for all texts", "\"documents[0].text has 20001 characters, above the 20000 this engine accepts\"", "\"documents has 5001 entries, above the 5000 this engine accepts\" for the list", "Nothing: the passage is cut at 20000 characters and ranked with a note about it"]'::jsonb, 1, 'The character cap applies to each text on its own, and a passage that breaks it is named by its position in the list, in the words quoted. The bare `text` wording is the tokenize call''s version of the same cap. The documents count cap is a different rule. No text is truncated: a cap either lets the call run exactly or refuses it.'),
  ('appliedai', 'advanced', 'final', null, 33, 'The query "the well top" is ranked with the stop list on. What happens, and why does the engine keep the list off by default?', '["The query ranks on well and top alone, since the list only removes the word the and other small function words", "It returns the note \"no document contains a query term\", as the corpus lacks the three words", "No document is ranked, as the query has no token left; the list removes well, top, bottom, fire and system", "A refusal naming `stopWords`, since a query made only of stop words cannot be passed to the engine at all"]'::jsonb, 2, 'scikit-learn''s list removes every token of that query, and the engine returns "the query has no token after the stop list, so no document is ranked" as a result with a note. The list removes words that carry meaning in oilfield text, well, top, bottom, fire and system among them, so the engine keeps it off. The stopWords refusal is for a switch that is not true or false.'),
  ('appliedai', 'advanced', 'final', null, 34, 'The query "oil oil rate" is scored on the hand set by BM25 and by TF-IDF. How do d1''s two figures compare with those for "oil rate"?', '["Both are unchanged, since each method keeps the distinct query terms and weights them the same", "BM25 rises above 2.191027, since oil now counts twice; the TF-IDF cosine stays at 0.715911", "Both move, BM25 to 1.750937 and the cosine to 0.679173, since the query is longer in each", "BM25 is unchanged at 2.191027, since a repeated query word counts once; the TF-IDF cosine moves to 0.679173"]'::jsonb, 3, 'BM25 keeps the distinct query terms (k3 = 0), so "oil oil rate" returns exactly the scores of "oil rate", d1 2.191027. TF-IDF weights the query like a passage, with raw counts, so its vector becomes oil 0.894427, rate 0.447214 and d1''s cosine falls from 0.715911 to 0.679173. 1.750937 is d1''s BM25 score at k1 = 0.'),
  ('appliedai', 'advanced', 'final', null, 35, 'On the stated ranking c, a, x, b, d with judgments a 3, b 2, c 0, d 1, e 2, nDCG at 5 with linear gain is 0.551774. Why does the ideal DCG count e?', '["It does not: the ideal ranks only the retrieved passages, and e was never retrieved by the run", "The ideal ranks every judged grade, retrieved or not, so a system is penalised for missing a good passage", "Because e is unjudged in the ranking and so counts as grade 0 there, lowering the ideal DCG", "Because e''s grade 2 is the median of the judged grades, and the ideal starts from the median"]'::jsonb, 1, 'The basis says the ideal ranks every judged grade descending, retrieved or not, here 3, 2, 2, 1, 0, which gives an ideal DCG of 5.692536 against the run''s 3.140995. Building the ideal from the retrieved passages alone would reward a system for missing e. e is judged grade 2 and never ranked; x is the unjudged passage. No median enters.'),
  ('appliedai', 'advanced', 'final', null, 36, 'System A''s extraction micro accuracy and macro accuracy, correct cells over cells, both print 0.972222. When may a report call them equal?', '["Always, since any two figures that agree at six decimals are the same number and may be called equal in a report", "Never, since micro and macro accuracy are computed differently and cannot be equal on any real set", "Only when the macro F1 also equals the micro F1, which on system A it does, at 0.966825 in both of the two cases", "When the reason is stated: every labelled record is scored on every field, so they are equal by construction"]'::jsonb, 3, 'Printed alike is not equal in general, and the course prints the differences, 1.11e-16 and 2.22e-16, and the reason before calling them equal: each field has the same 30 cells, so the mean of the per-field accuracies equals the pooled accuracy. Micro and macro F1 differ, 0.966825 against 0.942735, because filled cells differ by field.'),
  ('appliedai', 'advanced', 'final', null, 37, 'System B''s MRR at 5 is 0.923913 against system A''s 0.880435, while A has the higher MAP at grade 1. What does each figure reward?', '["MRR rewards where the first relevant passage sits; MAP rewards placing every relevant judged passage high", "MRR averages precision at every relevant rank; MAP counts only the first relevant passage found for each query", "Both reward the same thing, so the two orders disagree only through rounding at six decimals", "MRR divides by k and MAP by the passages ranked, so MRR favours whichever system returns the shorter lists"]'::jsonb, 0, 'Reciprocal rank is 1 / rank of the first relevant passage, so MRR is about the first hit; average precision sums precision at every relevant rank and divides by every relevant judged passage, so MAP rewards finding and ranking them all. They measure different things and can disagree, as here. Neither divides by k or by the passages ranked.'),
  ('appliedai', 'advanced', 'final', null, 38, 'System B''s pooled supported fraction is 0.731707, while the mean of its per-answer fractions is 0.687500. What separates the two?', '["The pooled figure uses numericRelTol 0.002; the mean uses the default of 0, so it is the lower", "The pooled figure counts every claim of every answer together; the mean averages the answers that have a claim", "The mean includes the answers with no claim at 0; the pooled figure leaves them out altogether", "The pooled figure counts only the cited passages; the mean counts every passage of the corpus"]'::jsonb, 1, 'The basis: supportedFraction pools every claim of every answer, 30 of 41 for system B, and meanAnswerSupportedFraction averages the answers that have at least one claim. Both use numericRelTol 0 here; at 0.002 the pooled fraction rises to 0.756098. An answer with no claim has a null fraction and is left out of the mean. Both figures use cited and retrieved passages.'),
  ('appliedai', 'advanced', 'final', null, 39, 'The paired nDCG bootstrap on seed 7 reports a share of 0.511000 at or below 0. What is that figure, and what does the engine compute from it?', '["The p-value of the difference, which the engine prints beside the interval as its test result", "A p-value needs an unpaired bootstrap, so it is reported only on the unpaired row, 0.505000", "The share of replicates in which A did not beat B, a count of replicates; the engine computes no p-value", "A refusal naming `paired`, returned because a paired comparison has no share to give"]'::jsonb, 2, 'The share at or below 0 is the share of replicates in which A did not beat B, a count of replicates, and the engine does not call it a p-value; the course lists a p-value among what is not built. The unpaired share, 0.505000, is also a share, and the `paired` refusal is for a value that is not true or false.'),
  ('appliedai', 'advanced', 'final', null, 40, 'Which statement about the Ekene second annotator''s grades is supported by the course?', '["They were written by a language model and checked by hand, and under them Q24 is still excluded from every mean", "They are the primary grades with every grade 1 raised to 2, so under them MAP and nDCG rise for both systems", "They were drawn from the primary grades by a stated synthetic rule, and under them no query is excluded from the means", "They cover only the passages system B retrieved, so under them system A''s figures cannot be computed at all"]'::jsonb, 2, 'The fixture draws each second grade from the primary one, moved one grade with probability 0.25 and two with probability 0.05, on a stated seed, and under those grades no query is excluded, so 24 enter the means. No language model wrote any fixture. Both systems'' MAP and nDCG fall under the second key, and the second annotator graded every judged pair.'),
  ('appliedai', 'advanced', 'final', null, 41, 'A copilot''s answer is fully supported by the passages it cites and retrieved. What else must be checked before it is called correct?', '["Nothing more: a fully supported answer is correct by the engine''s rule, so exact match adds nothing further to the verdict", "Its short answer against the reference, since a supported claim can come from a passage about another well", "Its kappa against a second annotator, since agreement on the grades is what makes any answer correct", "Its calibration, since a supported answer with a probability under 0.5 is counted as not correct"]'::jsonb, 1, 'Grounded is a statement about the passage and never about truth: system B''s Q05 date 2024-09-01 is supported by EKD-027, which is about Ekene-3, and its short answer scores exact match 0 against the reference 2024-03-01. Correctness is scored against a reference by exact match and token F1. Kappa measures raters, and calibration scores probabilities and never answers.'),
  ('appliedai', 'advanced', 'final', null, 42, 'The engine''s calibration bins follow numpy histogram''s edge rule where scikit-learn closes the lower bin. How should a report handle a reliability table compared across the two tools?', '["Convert the engine''s table to the library rule first, since the engine''s own rule is an error to fix", "Ignore the difference, since interior-edge probabilities never occur when they are given to 2 decimals", "Name the edge rule and the bin count, since the table and REL can differ under the other convention", "Report ECE alone, since it agrees under both rules on every set, whatever the bins and the rows"]'::jsonb, 2, 'Neither rule is an error; they are two conventions, and on the Ekene rows 6 of the 10 bins change their counts and REL moves from 0.080032 to 0.078849. Probabilities to 2 decimals do land on edges: 17 of them at 10 bins. ECE agrees on this set only because every bin is over-confident, which need not hold elsewhere, so the rule and the bin count are named.');
